    function initTheme() {
      const savedMode = localStorage.getItem('family_monefy_color_mode')
        || localStorage.getItem('app_theme')
        || ((['light', 'facebook'].includes(localStorage.getItem('family_monefy_theme'))) ? 'light' : 'dark');
      setAppColorMode(savedMode, false);
    }

    function setAppColorMode(mode, persist = true) {
      const target = mode === 'light' ? 'light' : 'dark';
      const isLight = target === 'light';
      document.body.classList.toggle('light-theme', isLight);
      document.documentElement.setAttribute('data-color-mode', target);
      document.body.setAttribute('data-color-mode', target);
      const icon = document.getElementById('themeIcon');
      if (icon) {
        icon.className = isLight ? 'fa-solid fa-sun' : 'fa-solid fa-moon';
        icon.style.color = isLight ? '#a16207' : '#cbd5e1';
      }
      ['appearanceModeDark', 'appearanceModeLight'].forEach(id => {
        const button = document.getElementById(id);
        if (!button) return;
        const selected = (id === 'appearanceModeLight') === isLight;
        button.classList.toggle('active', selected);
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
      });
      updateAppearanceAccent();
      if (!isInitializingApp) {
        const currentIconTheme = state.iconTheme || localStorage.getItem('family_monefy_icon_theme') || 'vibrant';
        setAppIconTheme(currentIconTheme, false);
        setAppTheme(state.appTheme || localStorage.getItem('family_monefy_theme') || 'navy', false);
        updateAppearancePreview();
      }
      if (persist) {
        try {
          localStorage.setItem('family_monefy_color_mode', target);
          localStorage.setItem('app_theme', target);
        } catch (e) {}
        if (typeof renderUI === 'function') renderUI();
        if (typeof updateAnalyticsChart === 'function') updateAnalyticsChart();
        if (typeof showToast === 'function') showToast(isLight ? 'تم تفعيل المظهر الفاتح ☀️' : 'تم تفعيل المظهر الداكن 🌙');
      }
    }

    function toggleTheme() {
      const next = document.body.classList.contains('light-theme') ? 'dark' : 'light';
      setAppColorMode(next);
    }

