            badge = '<span style="background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3); padding: 2px 5px; border-radius: 5px; font-weight: 800; font-size: 0.68rem; white-space: nowrap;"><i class="fa-solid fa-circle-check"></i> وفر</span>';
