    function setGlobalSearchFilter(f) {
      currentGlobalSearchFilter = f;
      document.querySelectorAll('#globalSearchFilters button').forEach(b => {
        if (b.getAttribute('data-filter') === f) b.classList.add('active');
        else b.classList.remove('active');
      });
      const inp = document.getElementById('inpGlobalSearchLive');
      runGlobalSearchLive(inp ? inp.value : '');
    }

    function runGlobalSearchLive(q) {
      q = (q || '').trim().toLowerCase();
      const container = document.getElementById('globalSearchResultsContainer');
      if (!container) return;

      const txList = state.transactions || [];
      const notesList = state.notes || [];
      const reqList = state.moneyRequests || [];
      const expList = state.expectedExpenses || [];

      let matchingTx = [], matchingNotes = [], matchingReq = [], matchingExp = [];

      if (!q) {
        matchingTx = txList.slice(0, 15);
        matchingNotes = notesList;
        matchingReq = reqList.slice(0, 5);
        matchingExp = expList.slice(0, 5);
      } else {
        matchingTx = txList.filter(t => 
          (t.label && t.label.toLowerCase().includes(q)) ||
          (t.member && t.member.toLowerCase().includes(q)) ||
          (t.category && t.category.toLowerCase().includes(q)) ||
          (t.amount && t.amount.toString().includes(q)) ||
          (t.date && t.date.includes(q))
        );

        matchingNotes = notesList.filter(n =>
          (n.title && n.title.toLowerCase().includes(q)) ||
          (n.content && n.content.toLowerCase().includes(q)) ||
          (n.member && n.member.toLowerCase().includes(q))
        );

        matchingReq = reqList.filter(r =>
          (r.reason && r.reason.toLowerCase().includes(q)) ||
          (r.member && r.member.toLowerCase().includes(q)) ||
          (r.amount && r.amount.toString().includes(q))
        );

        matchingExp = expList.filter(e =>
          (e.title && e.title.toLowerCase().includes(q)) ||
          (e.member && e.member.toLowerCase().includes(q)) ||
          (e.amount && e.amount.toString().includes(q))
        );
      }

      // تحديث عدادات الفلاتر
      const setC = (id, n) => { const el = document.getElementById(id); if (el) el.textContent = n.toLocaleString(); };
      const totalMatches = matchingTx.length + matchingNotes.length + matchingReq.length + matchingExp.length;
      setC('countSearchAll', totalMatches);
      setC('countSearchTx', matchingTx.length);
      setC('countSearchNotes', matchingNotes.length);
      setC('countSearchReq', matchingReq.length);
      setC('countSearchExp', matchingExp.length);

      if (totalMatches === 0) {
        container.innerHTML = `
          <div style="text-align: center; padding: 40px 10px; color: var(--text-muted);">
            <i class="fa-solid fa-face-meh" style="font-size: 2.2rem; opacity: 0.4; margin-bottom: 10px;"></i>
            <p style="font-size: 0.95rem; font-weight: 700;">لا توجد أي نتائج مطابقة لـ "${escapeHtml(q)}"</p>
          </div>
        `;
        return;
      }

      let html = '';

      // 1. الملاحظات
      if ((currentGlobalSearchFilter === 'all' || currentGlobalSearchFilter === 'notes') && matchingNotes.length > 0) {
        html += `<div style="font-size: 0.78rem; font-weight: 800; color: #fbbf24; margin: 8px 0 6px;"><i class="fa-solid fa-note-sticky"></i> الملاحظات (${matchingNotes.length}):</div>`;
        matchingNotes.forEach(n => {
          html += `
            <div class="note-item-card" style="margin-bottom: 6px; padding: 8px 12px;">
              <div class="note-card-title">${escapeHtml(n.title)} <span style="font-size: 0.68rem; color: #94a3b8;">${n.date}</span></div>
              <div class="note-card-content" style="font-size: 0.78rem;">${escapeHtml(n.content)}</div>
            </div>
          `;
        });
      }

      // 2. طلبات المصروف
      if ((currentGlobalSearchFilter === 'all' || currentGlobalSearchFilter === 'req') && matchingReq.length > 0) {
        html += `<div style="font-size: 0.78rem; font-weight: 800; color: #ec4899; margin: 10px 0 6px;"><i class="fa-solid fa-hand-holding-dollar"></i> طلبات المصروف (${matchingReq.length}):</div>`;
        matchingReq.slice(0, 10).forEach(r => {
          html += `
            <div style="background: rgba(15, 23, 42, 0.7); border: 1px solid var(--border-subtle); border-radius: 12px; padding: 8px 12px; margin-bottom: 6px; display: flex; justify-content: space-between; align-items: center;">
              <div>
                <div style="font-weight: 800; font-size: 0.82rem; color: #f1f5f9;">${escapeHtml(r.reason)}</div>
                <div style="font-size: 0.7rem; color: #94a3b8;">طالب النفقات: ${r.member} • ${r.date}</div>
              </div>
              <div style="text-align: left;">
                <div style="font-weight: 900; color: #f472b6;">${r.amount} ج.م</div>
                <span class="period-active-pill" style="font-size: 0.65rem; padding: 1px 6px;">${r.status === 'approved' ? 'معتمد' : r.status === 'pending' ? 'قيد المراجعة' : 'مرفوض'}</span>
              </div>
            </div>
          `;
        });
      }

      // 3. العمليات
      if ((currentGlobalSearchFilter === 'all' || currentGlobalSearchFilter === 'tx') && matchingTx.length > 0) {
        html += `<div style="font-size: 0.78rem; font-weight: 800; color: #38bdf8; margin: 10px 0 6px;"><i class="fa-solid fa-receipt"></i> العمليات والمصروفات (${matchingTx.length}):</div>`;
        matchingTx.slice(0, 25).forEach(tx => {
          const isExp = tx.type === 'expense';
          html += `
            <div style="background: rgba(15, 23, 42, 0.7); border: 1px solid var(--border-subtle); border-radius: 12px; padding: 8px 12px; margin-bottom: 6px; display: flex; justify-content: space-between; align-items: center;">
              <div>
                <div style="font-weight: 800; font-size: 0.82rem; color: #f1f5f9;">${escapeHtml(tx.label || 'حركة مسجلة')}</div>
                <div style="font-size: 0.7rem; color: #94a3b8;">${tx.member} • ${tx.date}</div>
              </div>
              <div style="font-weight: 900; font-size: 0.85rem; color: ${isExp ? '#ef4444' : '#10b981'}; direction: ltr;">
                ${isExp ? '- ' : '+ '}${parseFloat(tx.amount).toLocaleString('en-US')} ج.م
              </div>
            </div>
          `;
        });
      }

      container.innerHTML = html;
    }

