    let noteCurrentAttachedImage = null;

    function handleNoteImageSelect(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = function(e) {
        const rawUrl = e.target.result;
        // ضغط الصورة وتصغير حجمها لضمان السرعة والأداء العالي
        const img = new Image();
        img.onload = function() {
          const canvas = document.createElement('canvas');
          const maxDim = 600;
          let w = img.width, h = img.height;
          if (w > maxDim || h > maxDim) {
            if (w > h) { h = Math.round((h * maxDim) / w); w = maxDim; }
            else { w = Math.round((w * maxDim) / h); h = maxDim; }
          }
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          const compressed = canvas.toDataURL('image/jpeg', 0.70);

          noteCurrentAttachedImage = compressed;
          const previewContainer = document.getElementById('noteImagePreviewContainer');
          const previewImg = document.getElementById('noteImagePreviewImg');
          if (previewImg) previewImg.src = compressed;
          if (previewContainer) previewContainer.style.display = 'block';

          showToast('📸 تم التقاط / إرفاق الصورة بنجاح!');
        };
        img.src = rawUrl;
      };
      reader.readAsDataURL(file);
      event.target.value = '';
    }

    function clearNoteAttachedImage() {
      noteCurrentAttachedImage = null;
      const previewContainer = document.getElementById('noteImagePreviewContainer');
      const previewImg = document.getElementById('noteImagePreviewImg');
      if (previewImg) previewImg.src = '';
      if (previewContainer) previewContainer.style.display = 'none';
      showToast('تمت إزالة الصورة المرفقة');
    }

