    function getFilteredTransactions(includeProjectFilter = true) {
      let list = [...(state.transactions || [])];

      const projectFilter = state.projectFilter || 'all';
      if (includeProjectFilter) {
        if (projectFilter === '__no_project__') {
          list = list.filter(t => !getTransactionProjectName(t));
        } else if (projectFilter !== 'all') {
          list = list.filter(t => getTransactionProjectName(t) === projectFilter);
        }
      }

      // 1. تصفية أفراد العائلة (بند الكل إجمالي، بند البيت يشمل العائلة، وباقي الأفراد)
      if (state.currentMemberFilter && state.currentMemberFilter !== 'الكل') {
        if (state.currentMemberFilter === 'البيت') {
          list = list.filter(t => t.member === 'البيت' || t.member === 'العائلة' || !t.member);
        } else if (state.currentMemberFilter === 'أخرى' || state.currentMemberFilter === 'صدقات وأخرى') {
          list = list.filter(t => 
            t.member === 'أخرى' || 
            t.member === 'صدقات وأخرى' ||
            t.category === 'others' || 
            t.category === 'charity' || 
            (t.label && (t.label.includes('صدقة') || t.label.includes('تبرع') || t.label.includes('زكاة') || t.label.includes('مسجد') || t.label.includes('أخرى') || t.label.includes('إكرامية') || t.label.includes('نثريات')))
          );
        } else {
          list = list.filter(t => t.member === state.currentMemberFilter);
        }
      }

      // 2. تصفية المحفظة
      if (state.currentWalletId && state.currentWalletId !== 'all') {
        list = list.filter(t => t.walletId === state.currentWalletId);
      }

      // 3. فلترة الفترة الزمنية بدقة تامة بتوقيت التقويم المحلي
      const now = new Date();
      const todayStr = getLocalDateStr(now);

      if (state.period === 'day' || state.period === 'today') {
        list = list.filter(t => t.date === todayStr);
      } else if (state.period === 'week') {
        const sevenDaysAgo = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
        const sevenDaysAgoStr = getLocalDateStr(sevenDaysAgo);
        list = list.filter(t => operationDate(t) && operationDate(t) >= sevenDaysAgoStr && operationDate(t) <= todayStr);
      } else if (state.period === 'year') {
        const curYear = todayStr.slice(0, 4);
        list = list.filter(t => operationDate(t) && operationDate(t).startsWith(curYear));
      } else if (state.period === 'month') {
        const curYearMonth = todayStr.slice(0, 7);
        list = list.filter(t => operationDate(t).startsWith(curYearMonth));
      } else if (state.period === 'custom' && state.customDateRange) {
        const { from, to } = state.customDateRange;
        if (from && to) {
          list = list.filter(t => operationDate(t) && operationDate(t) >= from && operationDate(t) <= to);
        } else if (from) {
          list = list.filter(t => operationDate(t) && operationDate(t) >= from);
        } else if (to) {
          list = list.filter(t => operationDate(t) && operationDate(t) <= to);
        }
      }
      // إذا كانت الفترة 'all' تترك القائمة كاملة

      return list;
    }

    
    // =========================================================================
    // محرك الصور الفعلية لأفراد العائلة في كافة النماذج والاختيارات
    // =========================================================================
    

    function initMemberPhotoPickers() {
      // ضمان توفر صورة آية بكلا صيغتي الهمزة
      if (typeof MEMBER_AVATARS !== 'undefined') {
        if (!MEMBER_AVATARS['آية'] && MEMBER_AVATARS['أية']) MEMBER_AVATARS['آية'] = MEMBER_AVATARS['أية'];
        if (!MEMBER_AVATARS['أية'] && MEMBER_AVATARS['آية']) MEMBER_AVATARS['أية'] = MEMBER_AVATARS['آية'];
      }

      const members = [
        { id: 'البيت', name: 'البيت (مصروف عام)', photo: MEMBER_AVATARS['البيت'], icon: 'fa-house-chimney', color: '#0ea5e9' },
        { id: 'ماهر', name: 'ماهر', photo: MEMBER_AVATARS['ماهر'] },
        { id: 'أية', name: 'أية', photo: MEMBER_AVATARS['أية'] || MEMBER_AVATARS['آية'] },
        { id: 'محمد', name: 'محمد', photo: MEMBER_AVATARS['محمد'] },
        { id: 'مريم', name: 'مريم', photo: MEMBER_AVATARS['مريم'] },
        { id: 'الحاجة', name: 'الحاجة', photo: MEMBER_AVATARS['الحاجة'] },
        { id: 'النونو', name: 'النونو', photo: MEMBER_AVATARS['النونو'] },
        { id: 'أخرى', name: 'أخرى', icon: 'fa-wand-magic-sparkles', color: '#f59e0b' }
      ];

      const renderChips = (currentVal, clickFnName) => {
        return members.map(m => {
          const isActive = (m.id === currentVal || (m.id === 'أية' && (currentVal === 'آية' || currentVal === 'أية')));
          const imgHtml = m.photo 
            ? `<img src="${m.photo}" alt="${m.name}">`
            : `<div class="avatar-circle-fallback" style="background: ${m.color || '#14b8a6'}; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 0.95rem;"><i class="fa-solid ${m.icon || 'fa-users'}"></i></div>`;
          return `
            <div class="member-photo-chip ${isActive ? 'active' : ''}" onclick="${clickFnName}('${m.id}')" data-member-id="${m.id}">
              ${imgHtml}
              <span>${m.name.split(' ')[0]}</span>
            </div>
          `;
        }).join('');
      };

      // 1. منتقي مقدم الطلب (viewRequests)
      const reqPicker = document.getElementById('reqMemberPhotoPicker');
      if (reqPicker) {
        const currentReqVal = (document.getElementById('inpReqMember') ? document.getElementById('inpReqMember').value : 'أية') || 'أية';
        reqPicker.innerHTML = renderChips(currentReqVal, 'selectReqMemberPicker');
      }

      // 2. منتقي عضو الحركة في نافذة تسجيل المصروف (txModal)
      const txPicker = document.getElementById('txMemberPhotoPicker');
      if (txPicker) {
        const currentTxVal = (document.getElementById('inpTxMember') ? document.getElementById('inpTxMember').value : 'البيت') || 'البيت';
        txPicker.innerHTML = renderChips(currentTxVal, 'selectTxMemberPicker');
      }

      // 3. منتقي عضو الالتزامات والمصروفات المتوقعة (expectedExpenseModal)
      const expPicker = document.getElementById('expMemberPhotoPicker');
      if (expPicker) {
        const currentExpVal = (document.getElementById('inpExpMember') ? document.getElementById('inpExpMember').value : 'البيت') || 'البيت';
        expPicker.innerHTML = renderChips(currentExpVal, 'selectExpMemberPicker');
      }
    }
