        // وظيفة إخفاء وإظهار الأرقام الحساسة في قمرة القيادة (Privacy Mode)
    let isCockpitBalanceHidden = localStorage.getItem('app_balance_privacy') === 'true';

    function toggleBalancePrivacy() {
      isCockpitBalanceHidden = !isCockpitBalanceHidden;
      localStorage.setItem('app_balance_privacy', isCockpitBalanceHidden ? 'true' : 'false');
      renderUI();
    }

    function renderUI() {
      familyAlerts.refresh();
      refreshProjectSelectors();
      if (document.getElementById('btnMainTabWallets')?.getAttribute('aria-selected') === 'true') {
        populateWalletDropdowns();
        renderSecWalletStatementTable();
      }
      // 1. حساب الرصيد الفعلي التراكمي المعتمد لكافة المحافظ (السيولة النقدية الدائمة بالخزينة)
      const visibleWallets = (state.wallets || []).filter(wallet =>
        !state.currentWalletId || state.currentWalletId === 'all' || wallet.id === state.currentWalletId
      );
      const actualBalance = visibleWallets.reduce((sum, wallet) => sum + (Number(wallet.balance) || 0), 0);

      // 2. الحركات المفلترة بحسب الفترة الزمنية المختارة (اليوم / الأسبوع / الشهر / الكل / مخصص)
      const filtered = getFilteredTransactions(false);
      let periodInc = 0;
      let periodExp = 0;
      filtered.forEach(t => {
        if (t.type === 'transfer' || t.category === 'transfer') return;
        const amt = Number(t.amount) || 0;
        if (t.type === 'income') periodInc += amt;
        else if (t.type === 'expense') periodExp += amt;
      });

      // 3. تحديث قمرة القيادة المالية (Executive Wealth Cockpit):
      // - الرصيد الفعلي الحالي: يعرض السيولة التراكمية الحقيقية المعتمدة للمحافظ (actualBalance)
      // - كبسولتا التدفقات التوأم: تعرضان إيداعات ومصروفات الفترة المحددة بدقة (تتطابق 100% مع شبكة البنود وشاشة المؤشرات)
      const elInc = document.getElementById('topCardIncome');
      const elExp = document.getElementById('topCardExpense');
      const elBal = document.getElementById('topCardBalance');

      const privacyIcon = document.getElementById('iconBalancePrivacy');
      if (privacyIcon) {
        privacyIcon.className = isCockpitBalanceHidden ? 'fa-solid fa-eye-slash' : 'fa-solid fa-eye';
      }

      if (elInc) {
        if (isCockpitBalanceHidden) {
          elInc.textContent = '••••••';
        } else {
          elInc.innerHTML = formatMoneyWithSignHtml(periodInc, 'income');
        }
      }
      if (elExp) {
        if (isCockpitBalanceHidden) {
          elExp.textContent = '••••••';
        } else {
          elExp.innerHTML = formatMoneyWithSignHtml(periodExp, 'expense');
        }
      }
      if (elBal) {
        elBal.innerHTML = isCockpitBalanceHidden ? '••••••••' : formatMoneyWithSignHtml(actualBalance);
        const isLight = document.body.classList.contains('light-theme');
        if (isLight) {
          elBal.style.color = actualBalance >= 0 ? '#0284c7' : '#b91c1c';
        } else {
          elBal.style.color = actualBalance >= 0 ? '#38bdf8' : '#f43f5e';
        }

        // تحجيم ذكي ديناميكي متجاوب (Auto-Fit) يضمن بقاء الرقم ضخماً وبارزاً دون أي اقتصاص نهائياً
        const container = elBal.parentElement; // .cockpit-hero-side
        const maxW = (container ? container.clientWidth : 0) - 4;
        const balStr = elBal.textContent || '';
        
        let targetSize = 'clamp(1.40rem, 4.8vw, 1.95rem)';
        if (balStr.length > 22) {
          targetSize = 'clamp(1.10rem, 3.4vw, 1.35rem)';
        } else if (balStr.length > 17) {
          targetSize = 'clamp(1.28rem, 4.0vw, 1.62rem)';
        } else if (balStr.length > 12) {
          targetSize = 'clamp(1.42rem, 4.6vw, 1.82rem)';
        } else {
          targetSize = 'clamp(1.60rem, 5.2vw, 2.10rem)';
        }
        elBal.style.setProperty('font-size', targetSize, 'important');
        elBal.style.letterSpacing = '-0.3px';
        
        // فحص أمان هندسي بالبكسل: إذا كان النص أوسع من الحاوية على الشاشات الصغيرة يتم تقليصه تدريجياً بدقة
        if (maxW > 50) {
          let curPx = parseFloat(window.getComputedStyle(elBal).fontSize) || 22;
          while (elBal.scrollWidth > maxW && curPx > 14) {
            curPx -= 0.5;
            elBal.style.setProperty('font-size', curPx + 'px', 'important');
          }
        }

        // تحجيم ذكي لكبسولتي الإيداعات والمصروفات لتكون أرقامها أكبر وأبرز دون أي خروج عن الكارت
        function scaleFlowAmountPill(el) {
          if (!el) return;
          const s = el.textContent || '';
          if (s.length > 18) {
            el.style.setProperty('font-size', 'clamp(0.74rem, 2.25vw, 0.88rem)', 'important');
          } else if (s.length > 14) {
            el.style.setProperty('font-size', 'clamp(0.82rem, 2.5vw, 0.98rem)', 'important');
          } else {
            el.style.setProperty('font-size', 'clamp(0.90rem, 2.6vw, 1.00rem)', 'important');
          }
        }
        scaleFlowAmountPill(elInc);
        scaleFlowAmountPill(elExp);
      }

      // ضبط شارة وتلميح الفترة الزمنية لكبسولتي التدفقات
      const curPeriodCode = state.period || 'month';
      const periodShortNames = {
        'today': 'اليوم',
        'day': 'اليوم',
        'week': 'الأسبوع',
        'month': 'الشهر',
        'all': 'كافة الفترات',
        'custom': 'المخصصة'
      };
      const curPeriodLabel = periodShortNames[curPeriodCode] || 'الفترة';
      const pillInflow = document.querySelector('.cockpit-flow-pill.inflow');
      const pillOutflow = document.querySelector('.cockpit-flow-pill.outflow');
      if (pillInflow) pillInflow.setAttribute('title', `إجمالي إيداعات ${curPeriodLabel} (+${formatMoney(periodInc)}) - انقر لتسجيل أو استعراض الدخل`);
      if (pillOutflow) pillOutflow.setAttribute('title', `إجمالي مصروفات ${curPeriodLabel} (-${formatMoney(periodExp)}) - انقر لمراجعة عمليات المصروفات`);

      // تحديث شارة اسم الفترة وإجمالي مصروفها في شريط رأس البنود
      const p = state.period || 'month';
      const now = new Date();
      const periodLabels = {
        'today': 'اليوم (' + now.toLocaleDateString('ar-EG', { day: 'numeric', month: 'long' }) + ')',
        'day': 'اليوم',
        'week': 'الأسبوع الحالي (آخر 7 أيام)',
        'month': 'الشهر الحالي (' + now.toLocaleDateString('ar-EG', { month: 'long', year: 'numeric' }) + ')',
        'all': 'كافة الفترات (سجل العائلة الكامل)',
        'custom': 'فترة مخصصة'
      };
      const hintEl = document.getElementById('activeCategoryPeriodHint');
      if (hintEl) {
        hintEl.textContent = `${periodLabels[p] || p}: - ${formatMoney(periodExp)}`;
      }

      // 3. تحديث شبكة بنود المصاريف بألوانها وتفاصيلها الموزونة
      renderCategoriesGrid(filtered);

      // 4. تمييز الأفاتار المختار في الشريط العلوي
      const memberCards = document.querySelectorAll('.avatar-card');
      memberCards.forEach(card => {
        const m = card.getAttribute('data-member');
        if (m === state.currentMemberFilter) {
          card.classList.add('active');
        } else {
          card.classList.remove('active');
        }
      });

      // 5. تحديث محتويات الصفحة النشطة فقط بذكاء وسرعة فائقة استجابة لطلب المستخدم (Ultra-Fast 60fps Lazy Rendering)
      const activeP = state.activePage || 'expenses';
      if (activeP === 'expenses') {
        // الصفحة الرئيسية تم تحديث قمرتها وبنودها فوراً في أجزاء من الميلي ثانية
      } else if (activeP === 'operations') {
        if (typeof filterOperationsList === 'function') filterOperationsList();
        if (state.activeOpsSubTab === 'archive' && typeof renderActivityLogUI === 'function') renderActivityLogUI();
      } else if (activeP === 'analytics') {
        try {
          if (typeof updateAnalyticsChart === 'function') updateAnalyticsChart();
          if (activeAnalyticsMainTab === 'comparisons' && typeof renderComparisonsSection === 'function') renderComparisonsSection();
          if (state.activeCategoryFilter && typeof showCategoryDetailBanner === 'function') {
            showCategoryDetailBanner(state.activeCategoryFilter);
          }
        } catch(e) { console.warn('updateAnalyticsChart error:', e); }
      } else if (activeP === 'requests') {
        if (typeof renderRequestsList === 'function') renderRequestsList();
      } else if (activeP === 'expected') {
        if (typeof renderExpectedList === 'function') renderExpectedList();
      }
    }

    
    // =========================================================================
    // LIVE CATEGORY BUDGET CEILINGS ENGINE (محرك سقوف الإنفاق الذكية والحية)
    // =========================================================================
    function getActiveMonthBudgetPlan() {
      if (!Array.isArray(state.monthlyBudgets) || state.monthlyBudgets.length === 0) return null;
      const nowMonth = (typeof getLocalDateStr === 'function' ? getLocalDateStr(new Date()) : new Date().toISOString()).slice(0, 7);
      
      // 1. الخطة المطابقة للشهر الحالي غير المرتبطة بمشروع
      let plan = state.monthlyBudgets.find(b => !b.project && b.month === nowMonth);
      // 2. أو الخطة النشطة حالياً إن كانت غير مرتبطة بمشروع
      if (!plan && state.activeBudgetId) {
        plan = state.monthlyBudgets.find(b => b.id === state.activeBudgetId && !b.project);
      }
      // 3. أو أول خطة عامة متاحة
      if (!plan) {
        plan = state.monthlyBudgets.find(b => !b.project) || state.monthlyBudgets[0];
      }
      return plan;
    }
    window.getActiveMonthBudgetPlan = getActiveMonthBudgetPlan;

    function getCategoryBudgetCeilings() {
      const plan = getActiveMonthBudgetPlan();
      if (!plan) return {};
      const ceilings = {};

      // 1. قراءة كائن التصنيفات إن وُجد (categories map)
      if (plan.categories && typeof plan.categories === 'object') {
        Object.entries(plan.categories).forEach(([catKey, amt]) => {
          let k = catKey;
          if (k === 'home') k = 'house';
          if (k === 'apparel') k = 'clothes';
          if (k === 'shopping' || k === 'supermarket') k = 'food';
          if (k === 'others') k = 'other';
          ceilings[k] = (ceilings[k] || 0) + (Number(amt) || 0);
        });
      }

      // 2. قراءة مصفوفة البنود التفصيلية (items array) كمصدر أولي أدق
      if (Array.isArray(plan.items) && plan.items.length > 0) {
        const itemsCeilings = {};
        plan.items.forEach(it => {
          let k = it.category;
          if (k === 'home') k = 'house';
          if (k === 'apparel') k = 'clothes';
          if (k === 'shopping' || k === 'supermarket') k = 'food';
          if (k === 'others') k = 'other';
          if (!k && it.title) {
            const found = EXPENSE_CATEGORIES.find(c => it.title.includes(c.name) || c.name.includes(it.title));
            if (found) k = found.id;
          }
          if (k) {
            itemsCeilings[k] = (itemsCeilings[k] || 0) + (Number(it.amount) || 0);
          }
        });
        Object.entries(itemsCeilings).forEach(([k, amt]) => {
          ceilings[k] = amt;
        });
      }

      return ceilings;
    }
    window.getCategoryBudgetCeilings = getCategoryBudgetCeilings;

    // تنبيه لحظي عند الاقتراب من سقف الميزانية (> 85%) أو تجاوزه (> 100%)
    function checkCategoryBudgetCeilingTrigger(catId, addedAmt) {
      if (!catId) return;
      let k = catId;
      if (k === 'shopping' || k === 'supermarket') k = 'food';
      if (k === 'home') k = 'house';
      if (k === 'apparel') k = 'clothes';
      if (k === 'kids' || k === 'gifts' || k === 'entertainment' || k === 'others') k = 'other';

      const ceilings = getCategoryBudgetCeilings();
      const ceiling = ceilings[k] || 0;
      if (ceiling <= 0) return;

      const currentMonth = (typeof getLocalDateStr === 'function' ? getLocalDateStr(new Date()) : new Date().toISOString()).slice(0, 7);
      const totalSpent = (state.transactions || []).filter(t => 
        t.type === 'expense' && 
        (t.category === k || (k === 'food' && (t.category === 'shopping' || t.category === 'supermarket')) || (k === 'other' && (t.category === 'entertainment' || t.category === 'others' || t.category === 'gifts' || t.category === 'kids'))) && 
        !t.deleted && 
        (t.date || '').startsWith(currentMonth)
      ).reduce((s, t) => s + (Number(t.amount) || 0), 0);

      const pct = Math.round((totalSpent / ceiling) * 100);
      const catObj = EXPENSE_CATEGORIES.find(c => c.id === k);
      const catName = catObj ? catObj.name : 'بند المصروف';

      if (pct >= 100) {
        const overAmt = typeof formatMoneyVal === 'function' ? formatMoneyVal(totalSpent - ceiling) : (totalSpent - ceiling).toFixed(2);
        showToast(`⚠️ تنبيه الميزانية: تم تجاوز سقف ميزانية بند "${catName}" لهذا الشهر! (استهلاك ${pct}% - تجاوز ${overAmt} ج.م)`, 'error', 5500);
        if (window.FamilyAlerts && typeof window.FamilyAlerts.created === 'function') {
          window.FamilyAlerts.created('budget_exceeded', {
            id: `budget_alert_${k}_${Date.now()}`,
            title: 'تنبيه تجاوز الميزانية',
            message: `تم تخطي سقف ميزانية بند "${catName}" لشهر ${currentMonth} بنسبة ${pct}% (المنصرف: ${typeof formatMoneyVal === 'function' ? formatMoneyVal(totalSpent) : totalSpent} ج.م من أصل ${typeof formatMoneyVal === 'function' ? formatMoneyVal(ceiling) : ceiling} ج.م).`
          });
        }
      } else if (pct >= 85) {
        showToast(`⚠️ تنبيه الميزانية: استهلكت ${pct}% من ميزانية بند "${catName}" لهذا الشهر`, 'warning', 4500);
        if (window.FamilyAlerts && typeof window.FamilyAlerts.created === 'function') {
          window.FamilyAlerts.created('budget_warning', {
            id: `budget_alert_${k}_${Date.now()}`,
            title: 'تنبيه اقتراب سقف الميزانية',
            message: `اقترب استهلاك بند "${catName}" من الحد الأقصى (${pct}% من أصل ${typeof formatMoneyVal === 'function' ? formatMoneyVal(ceiling) : ceiling} ج.م).`
          });
        }
      }
    }
    window.checkCategoryBudgetCeilingTrigger = checkCategoryBudgetCeilingTrigger;
    window.renderCategoriesGrid = renderCategoriesGrid;
    window.renderUI = renderUI;
    window.getFilteredTransactions = getFilteredTransactions;

    let isRenderingCategoryGrid = false;
    function renderCategoriesGrid(filtered) {
      if (isRenderingCategoryGrid) return;
      isRenderingCategoryGrid = true;
      try {
        const activeHomeLayout = (window.HomeLayouts && typeof window.HomeLayouts.getLayout === 'function')
          ? window.HomeLayouts.getLayout()
          : (parseInt(localStorage.getItem('family_expense_home_design_v2'), 10) || 0);

        if (activeHomeLayout > 0) {
          const grid = document.getElementById('catGrid');
          if (grid) {
            grid.hidden = true;
            grid.style.setProperty('display', 'none', 'important');
          }
          const container = document.getElementById('homeInterfaces');
          if (container) {
            container.hidden = false;
            container.style.removeProperty('display');
          }
          if (window.HomeLayouts && typeof window.HomeLayouts.render === 'function') {
            window.HomeLayouts.render(filtered);
          }
          return;
        }

        const grid = document.getElementById('catGrid');
        if (!grid) return;
        grid.hidden = false;
        grid.style.removeProperty('display');
        grid.style.setProperty('display', 'grid', 'important');

        const container = document.getElementById('homeInterfaces');
        if (container) {
          container.hidden = true;
          container.style.setProperty('display', 'none', 'important');
        }

      const catTotals = {};
      (filtered || []).forEach(t => {
        if (t.type === 'expense' && t.category !== 'transfer') {
          let c = t.category;
          if (c === 'shopping' || c === 'supermarket') c = 'food';
          if (c === 'kids' || c === 'gifts' || c === 'entertainment') c = 'other';
          if (c === 'others') c = 'other';
          catTotals[c] = (catTotals[c] || 0) + (Number(t.amount) || 0);
        }
      });

      // جلب سقوف الميزانيات الحية للشهر الحالي
      const categoryBudgets = (typeof getCategoryBudgetCeilings === 'function') ? getCategoryBudgetCeilings() : {};
      const activePlan = (typeof getActiveMonthBudgetPlan === 'function') ? getActiveMonthBudgetPlan() : null;
      const activePlanId = activePlan ? String(activePlan.id || '') : 'none';

      const HIGH_CONTRAST_THEMES = {
        food: { name: 'طعام ومشتريات', emoji: '🛒', accent: '#10b981', gradient: 'linear-gradient(135deg, #10b981 0%, #047857 100%)' },
        daily: { name: 'مصروف يومي', emoji: '☕', accent: '#f59e0b', gradient: 'linear-gradient(135deg, #f59e0b 0%, #b45309 100%)' },
        bills: { name: 'فواتير والتزامات', emoji: '⚡', accent: '#f97316', gradient: 'linear-gradient(135deg, #f97316 0%, #c2410c 100%)' },
        transport: { name: 'مواصلات وبنزين', emoji: '🚗', accent: '#0284c7', gradient: 'linear-gradient(135deg, #0284c7 0%, #0369a1 100%)' },
        house: { name: 'مستلزمات منزل', emoji: '🛋️', accent: '#8b5cf6', gradient: 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)' },
        health: { name: 'صحة وعلاج', emoji: '💊', accent: '#ef4444', gradient: 'linear-gradient(135deg, #ef4444 0%, #b91c1c 100%)' },
        clothes: { name: 'ملابس وأحذية', emoji: '👔', accent: '#ec4899', gradient: 'linear-gradient(135deg, #ec4899 0%, #be185d 100%)' },
        education: { name: 'تعليم ودروس', emoji: '📚', accent: '#3b82f6', gradient: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)' },
        other: { name: 'أخرى ونثريات', emoji: '🎁', accent: '#14b8a6', gradient: 'linear-gradient(135deg, #14b8a6 0%, #0f766e 100%)' }
      };

      const activeTheme = state.appTheme || localStorage.getItem('family_monefy_theme') || 'navy';
      const isLight = (activeTheme === 'light') || document.body.classList.contains('light-theme');
      const isGold = state.currency === 'GOLD21';
      const currSymbol = getCurrencySymbol();

      const THEME_CARD_PALETTES = {
        facebook: {
          bgGrad: (c) => isLight 
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}40 0%, #172554 40%, #0c1a30 100%)`,
          lowerZero: isLight ? 'rgba(240, 242, 245, 0.95)' : 'rgba(12, 26, 48, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}dd`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 14px ${c}40`
        },
        navy: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}42 0%, ${c}15 38%, #08162b 100%)`,
          lowerZero: isLight ? 'rgba(241, 245, 249, 0.95)' : 'rgba(8, 22, 43, 0.88)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.28)',
          border: (c) => `${c}cc`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.5), 0 0 12px ${c}35, inset 0 1px 0 rgba(255, 255, 255, 0.15)`
        },
        black: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}12 45%, ${c}25 100%)`
            : `linear-gradient(160deg, ${c}30 0%, #111827 50%, #030508 100%)`,
          lowerZero: isLight ? 'rgba(241, 245, 249, 0.95)' : '#060a10',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.32)',
          border: (c) => `${c}bb`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08)` : `0 4px 20px rgba(0, 0, 0, 0.7), 0 0 10px ${c}25`
        },
        emerald: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}40 0%, #064e3b 40%, #022c22 100%)`,
          lowerZero: isLight ? 'rgba(240, 253, 244, 0.95)' : 'rgba(2, 44, 34, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}dd`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 14px ${c}40`
        },
        purple: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}40 0%, #3b0764 40%, #1e1b4b 100%)`,
          lowerZero: isLight ? 'rgba(250, 245, 255, 0.95)' : 'rgba(30, 27, 75, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}dd`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 14px ${c}40`
        },
        rose: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}40 0%, #4c0519 40%, #2d0b1d 100%)`,
          lowerZero: isLight ? 'rgba(255, 241, 242, 0.95)' : 'rgba(45, 11, 29, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}dd`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 14px ${c}40`
        },
        ocean: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}40 0%, #083344 40%, #041624 100%)`,
          lowerZero: isLight ? 'rgba(240, 249, 255, 0.95)' : 'rgba(8, 51, 68, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}dd`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 14px ${c}40`
        },
        gold: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}38 0%, #3a2803 40%, #1c1301 100%)`,
          lowerZero: isLight ? 'rgba(254, 252, 232, 0.95)' : 'rgba(38, 26, 3, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}dd`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 14px ${c}40`
        },
        slate: {
          bgGrad: (c) => isLight
            ? `linear-gradient(160deg, #ffffff 0%, ${c}15 45%, ${c}28 100%)`
            : `linear-gradient(160deg, ${c}35 0%, #1e293b 40%, #0f172a 100%)`,
          lowerZero: isLight ? 'rgba(241, 245, 249, 0.95)' : 'rgba(15, 23, 42, 0.90)',
          lowerSpent: isLight ? 'rgba(254, 226, 226, 0.95)' : 'rgba(239, 68, 68, 0.30)',
          border: (c) => `${c}cc`,
          shadow: (c) => isLight ? `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20` : `0 4px 18px rgba(0, 0, 0, 0.55), 0 0 12px ${c}35`
        },
        light: {
          bgGrad: (c) => `linear-gradient(160deg, #ffffff 0%, ${c}12 45%, ${c}25 100%)`,
          lowerZero: 'rgba(241, 245, 249, 0.95)',
          lowerSpent: 'rgba(254, 226, 226, 0.95)',
          border: (c) => `${c}cc`,
          shadow: (c) => `0 4px 14px rgba(0, 0, 0, 0.08), 0 0 8px ${c}20`
        }
      };

      const pal = THEME_CARD_PALETTES[activeTheme] || THEME_CARD_PALETTES.navy;
      const activeIconTheme = state.iconTheme || localStorage.getItem('family_monefy_icon_theme') || 'vibrant';
      const iconPalette = APPEARANCE_ICON_THEMES[activeIconTheme] || APPEARANCE_ICON_THEMES.vibrant;
      const iconColor = isLight ? iconPalette.light : iconPalette.dark;
      const cardIconBg = `linear-gradient(145deg, ${iconColor}bd 0%, ${iconColor}69 100%)`;
      const activeCardStyle = document.body.getAttribute('data-card-style') || 'glass';
      const colorMode = isLight ? 'light' : 'dark';
      const getCardTopBackground = (accent) => isLight
        ? `linear-gradient(145deg, ${accent}38 0%, ${accent}1f 56%, ${accent}12 100%)`
        : `linear-gradient(145deg, ${accent}60 0%, ${accent}3c 56%, ${accent}25 100%)`;

      const existingCards = grid.querySelectorAll('.cat-card');
      const curFontSize = document.documentElement.getAttribute('data-font-size') || 'medium';
      const curFontFamily = document.documentElement.getAttribute('data-font-family') || 'tajawal';
      
      const needRebuild = (existingCards.length !== EXPENSE_CATEGORIES.length) || 
                          (grid.dataset.theme !== activeTheme) ||
                          (grid.dataset.iconTheme !== activeIconTheme) ||
                          (grid.dataset.cardStyle !== activeCardStyle) ||
                          (grid.dataset.colorMode !== colorMode) ||
                          (grid.dataset.fontSize !== curFontSize) ||
                          (grid.dataset.fontFamily !== curFontFamily) ||
                          (grid.dataset.activeBudgetId !== activePlanId);

      if (needRebuild) {
        grid.innerHTML = '';
        grid.dataset.theme = activeTheme;
        grid.dataset.iconTheme = activeIconTheme;
        grid.dataset.cardStyle = activeCardStyle;
        grid.dataset.colorMode = colorMode;
        grid.dataset.fontSize = curFontSize;
        grid.dataset.fontFamily = curFontFamily;
        grid.dataset.activeBudgetId = activePlanId;

        EXPENSE_CATEGORIES.forEach(cat => {
          const spent = catTotals[cat.id] || (cat.id === 'other' ? (catTotals['entertainment'] || 0) : 0);
          const theme = HIGH_CONTRAST_THEMES[cat.id] || {
            name: cat.name,
            emoji: '📦',
            accent: cat.color || '#38bdf8',
            gradient: `linear-gradient(135deg, ${cat.color}, #334155)`
          };

          const isFlatCard = activeCardStyle === 'flat';
          const cardBg = isFlatCard ? (isLight ? '#ffffff' : '#17243a') : pal.bgGrad(theme.accent);
          const cardBorder = isFlatCard
            ? `1px solid ${isLight ? '#cbd5e1' : '#475569'}`
            : `2px solid ${pal.border(theme.accent)}`;
          const cardShadow = isFlatCard ? 'none' : pal.shadow(theme.accent);
          const cardTopBg = isFlatCard
            ? (isLight ? 'rgba(241,245,249,.85)' : 'rgba(255,255,255,.04)')
            : getCardTopBackground(theme.accent);

          const converted = convertAmount(spent);
          let numStr = '0.00';
          if (spent > 0) {
            numStr = converted.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: isGold ? 3 : 2 });
          }
          const signStr = (spent > 0) ? '-' : '';

          let amtFontSize = 'clamp(0.88rem, 2.6vw, 0.98rem)';
          let amtLetterSpacing = '-0.2px';
          const totalLen = numStr.length;
          if (totalLen >= 14 || isGold) {
            amtFontSize = 'clamp(0.64rem, 1.8vw, 0.74rem)';
            amtLetterSpacing = '-0.5px';
          } else if (totalLen >= 10) {
            amtFontSize = 'clamp(0.72rem, 2.1vw, 0.82rem)';
            amtLetterSpacing = '-0.4px';
          } else if (totalLen >= 7) {
            amtFontSize = 'clamp(0.80rem, 2.4vw, 0.90rem)';
            amtLetterSpacing = '-0.3px';
          }

          const lowerCardBg = spent > 0 ? pal.lowerSpent : pal.lowerZero;
          const lowerCardBorder = spent > 0 
            ? (isLight ? 'rgba(239, 68, 68, 0.6)' : '#f43f5e') 
            : (isLight ? 'rgba(203, 213, 225, 0.8)' : `${theme.accent}55`);
          const amtColor = spent > 0 
            ? (isLight ? '#b91c1c' : '#ff4d6d') 
            : (isLight ? '#334155' : '#f1f5f9');

          // حسابات سقف الميزانية الذكي للبند الحالي
          const budgetCeiling = categoryBudgets[cat.id] || 0;
          let ceilingHtml = '';
          let isPulseAlert = false;

          if (budgetCeiling > 0) {
            const remaining = budgetCeiling - spent;
            const pct = Math.round((spent / budgetCeiling) * 100);
            let statusColor = '#10b981';
            let remainingText = '';

            const isOver = remaining < 0;
            const convertedRem = typeof convertAmount === 'function' ? convertAmount(remaining) : remaining;
            const roundedRem = Math.round(Math.abs(convertedRem || 0)).toLocaleString('en-US');
            const remCurr = typeof getCurrencySymbol === 'function' ? getCurrencySymbol() : (state.currency || 'ج.م');

            const remainingPct = isOver ? Math.round((Math.abs(remaining) / budgetCeiling) * 100) : Math.max(0, 100 - pct);
            if (isOver) {
              statusColor = '#ef4444';
              isPulseAlert = true;
              remainingText = `تجاوز: ${remainingPct}% • -${roundedRem} ${remCurr}`;
            } else {
              statusColor = pct < 70 ? '#10b981' : (pct <= 90 ? '#f59e0b' : '#ef4444');
              remainingText = `متبقي: ${remainingPct}% • ${roundedRem} ${remCurr}`;
            }

            ceilingHtml = `
              <div class="cat-budget-ceiling-wrap" style="width: 100%; display: flex; flex-direction: column; gap: 2px; margin-top: 2px; padding: 0 1px; box-sizing: border-box;">
                <div class="cat-budget-progress-track" style="width: 100%; height: 3px; background: ${isLight ? 'rgba(0,0,0,0.12)' : 'rgba(255,255,255,0.15)'}; border-radius: 2px; overflow: hidden;">
                  <div class="cat-budget-progress-fill" style="width: ${Math.min(pct, 100)}%; height: 100%; background: ${statusColor}; border-radius: 2px; transition: width 0.3s ease;"></div>
                </div>
                <div class="cat-budget-ceiling-text" style="font-size: 0.58rem; font-weight: 850; color: ${statusColor}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; line-height: 1.1; font-family: var(--font-numbers); direction: rtl;">
                  ${remainingText}
                </div>
              </div>
            `;
          }

          const card = document.createElement('div');
          card.className = `cat-card cat-theme-${cat.id} ${isPulseAlert ? 'budget-pulse-alert' : ''}`;
          card.setAttribute('data-cat-id', cat.id);
          card.style.cssText = `
            background: ${cardBg} !important;
            border: ${cardBorder} !important;
            border-radius: ${activeCardStyle === 'flat' ? '9px' : '16px'} !important;
            padding: 0 !important;
            display: flex !important;
            flex-direction: column !important;
            align-items: stretch !important;
            justify-content: space-between !important;
            height: 100% !important;
            max-height: var(--app-card-max-h, 140px) !important;
            min-height: 0 !important;
            box-shadow: ${cardShadow} !important;
            transition: all 0.22s ease !important;
            position: relative !important;
            box-sizing: border-box !important;
            overflow: hidden !important;
            touch-action: manipulation !important;
            contain: content !important;
          `;

          card.innerHTML = `
            <div class="cat-card-top-half" 
                 onclick="event.stopPropagation(); openQuickCategoryExpense('${cat.id}');"
                 title="انقر على الرمز لتسجيل مصروف جديد في ${theme.name}"
                 style="flex: 1.25 1 65%; min-height: 0; width: 100%; align-self: stretch; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; padding: 3px 2px 1px; background: ${cardTopBg}; border-radius: 14px 14px 0 0; cursor: pointer; transition: background 0.15s ease; box-sizing: border-box; overflow: hidden; touch-action: manipulation;">
              
              <div class="cat-icon-bubble" 
                   style="background: ${cardIconBg}; width: clamp(34px, 9vw, 40px) !important; height: clamp(34px, 9vw, 40px) !important; min-width: 34px !important; min-height: 34px !important; border-radius: 12px; display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 14px ${iconColor}66, inset 0 0 6px rgba(255, 255, 255, 0.24); border: 2px solid rgba(255, 255, 255, 0.75); outline: 1.8px solid ${iconColor}; flex-shrink: 0;">
                <span style="font-size: clamp(1.4rem, 3.6vw, 1.7rem) !important; line-height: 1; filter: drop-shadow(0 3px 5px rgba(0,0,0,0.5));">${theme.emoji}</span>
              </div>

              <div class="cat-label-text" 
                   style="font-family: var(--font-family); font-size: clamp(0.70rem, 1.9vw, 0.80rem); font-weight: 900; color: ${isLight ? '#0f172a' : '#ffffff'} !important; text-shadow: ${isLight ? 'none' : '0 1px 3px rgba(0,0,0,0.95)'}; text-align: center; margin: 0; line-height: 1.15; white-space: normal; overflow: hidden; text-overflow: clip; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; min-height: 2.3em; width: 100%; max-width: 100%; padding: 0 2px; box-sizing: border-box;">
                ${theme.name}
              </div>
            </div>

            <div class="cat-card-bottom-half ${spent > 0 ? 'has-spent' : 'zero-spent'}" 
                 onclick="event.stopPropagation(); openOperationsFiltered({ category: '${cat.id}', categoryName: '${cat.name}', type: 'expense' });" 
                 title="انقر لعرض حركات ${theme.name}" 
                 style="flex: 0.75 1 35%; min-height: 0; width: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 2px 2px 3px; cursor: pointer; background: ${lowerCardBg}; border-top: 1.5px solid ${lowerCardBorder}; box-sizing: border-box; transition: all 0.15s ease; overflow: hidden; touch-action: manipulation;">
              <div class="cat-amount-val" 
                   style="font-family: var(--font-numbers); font-size: ${amtFontSize}; letter-spacing: ${amtLetterSpacing}; font-weight: 950; color: ${amtColor}; line-height: 1.15; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; width: 100%; max-width: 100%; direction: rtl; text-align: center; font-variant-numeric: tabular-nums; display: flex; align-items: baseline; justify-content: center; gap: 2px; box-sizing: border-box; padding: 0 1px;">
                ${signStr ? `<span class="cat-amount-sign">${signStr}</span>` : ''}
                <span class="cat-number-val">${numStr}</span>
                <span class="cat-currency-label">${currSymbol}</span>
              </div>
              ${ceilingHtml}
            </div>
          `;
          grid.appendChild(card);
        });
      } else {
        // Fast in-place DOM updates with live budget ceilings
        EXPENSE_CATEGORIES.forEach(cat => {
          const card = grid.querySelector(`[data-cat-id="${cat.id}"]`);
          if (!card) return;
          const spent = catTotals[cat.id] || (cat.id === 'other' ? (catTotals['entertainment'] || 0) : 0);
          const theme = HIGH_CONTRAST_THEMES[cat.id] || { accent: cat.color || '#38bdf8' };
          const converted = convertAmount(spent);
          let numStr = '0.00';
          if (spent > 0) {
            numStr = converted.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: isGold ? 3 : 2 });
          }
          const signStr = (spent > 0) ? '-' : '';

          let amtFontSize = 'clamp(0.88rem, 2.6vw, 0.98rem)';
          let amtLetterSpacing = '-0.2px';
          const totalLen = numStr.length;
          if (totalLen >= 14 || isGold) {
            amtFontSize = 'clamp(0.64rem, 1.8vw, 0.74rem)';
            amtLetterSpacing = '-0.5px';
          } else if (totalLen >= 10) {
            amtFontSize = 'clamp(0.72rem, 2.1vw, 0.82rem)';
            amtLetterSpacing = '-0.4px';
          } else if (totalLen >= 7) {
            amtFontSize = 'clamp(0.80rem, 2.4vw, 0.90rem)';
            amtLetterSpacing = '-0.3px';
          }

          card.style.setProperty('background', activeCardStyle === 'flat' ? (isLight ? '#ffffff' : '#17243a') : pal.bgGrad(theme.accent), 'important');
          card.style.setProperty('border-color', activeCardStyle === 'flat' ? (isLight ? '#cbd5e1' : '#475569') : pal.border(theme.accent), 'important');
          card.style.setProperty('box-shadow', activeCardStyle === 'flat' ? 'none' : pal.shadow(theme.accent), 'important');

          const lowerHalf = card.querySelector('.cat-card-bottom-half');
          const amtEl = card.querySelector('.cat-amount-val');
          if (lowerHalf && amtEl) {
            const amtColor = spent > 0 ? (isLight ? '#b91c1c' : '#ff4d6d') : (isLight ? '#334155' : '#f1f5f9');
            const lowerBg = spent > 0 ? pal.lowerSpent : pal.lowerZero;
            lowerHalf.style.background = lowerBg;
            amtEl.style.fontSize = amtFontSize;
            amtEl.style.letterSpacing = amtLetterSpacing;
            amtEl.style.color = amtColor;
            amtEl.innerHTML = `
              ${signStr ? `<span class="cat-amount-sign">${signStr}</span>` : ''}
              <span class="cat-number-val">${numStr}</span>
              <span class="cat-currency-label">${currSymbol}</span>
            `;

            // تحديث شريط سقف الميزانية اللحظي
            const budgetCeiling = categoryBudgets[cat.id] || 0;
            let ceilingWrap = lowerHalf.querySelector('.cat-budget-ceiling-wrap');
            
            if (budgetCeiling > 0) {
              const remaining = budgetCeiling - spent;
              const pct = Math.round((spent / budgetCeiling) * 100);
              let statusColor = '#10b981';
              let remainingText = '';

              const isOver = remaining < 0;
              const convertedRem = typeof convertAmount === 'function' ? convertAmount(remaining) : remaining;
              const roundedRem = Math.round(Math.abs(convertedRem || 0)).toLocaleString('en-US');
              const remCurr = typeof getCurrencySymbol === 'function' ? getCurrencySymbol() : (state.currency || 'ج.م');

              const remainingPct = isOver ? Math.round((Math.abs(remaining) / budgetCeiling) * 100) : Math.max(0, 100 - pct);
              if (isOver) {
                statusColor = '#ef4444';
                remainingText = `تجاوز: ${remainingPct}% • -${roundedRem} ${remCurr}`;
              } else {
                statusColor = pct < 70 ? '#10b981' : (pct <= 90 ? '#f59e0b' : '#ef4444');
                remainingText = `متبقي: ${remainingPct}% • ${roundedRem} ${remCurr}`;
              }

              card.classList.toggle('budget-pulse-alert', pct > 90);

              if (ceilingWrap) {
                const fill = ceilingWrap.querySelector('.cat-budget-progress-fill');
                const txt = ceilingWrap.querySelector('.cat-budget-ceiling-text');
                if (fill) {
                  fill.style.width = Math.min(pct, 100) + '%';
                  fill.style.background = statusColor;
                }
                if (txt) {
                  txt.innerHTML = remainingText;
                  txt.style.color = statusColor;
                }
              } else {
                const newWrap = document.createElement('div');
                newWrap.className = 'cat-budget-ceiling-wrap';
                newWrap.style.cssText = 'width: 100%; display: flex; flex-direction: column; gap: 2px; margin-top: 2px; padding: 0 1px; box-sizing: border-box;';
                newWrap.innerHTML = `
                  <div class="cat-budget-progress-track" style="width: 100%; height: 3px; background: ${isLight ? 'rgba(0,0,0,0.12)' : 'rgba(255,255,255,0.15)'}; border-radius: 2px; overflow: hidden;">
                    <div class="cat-budget-progress-fill" style="width: ${Math.min(pct, 100)}%; height: 100%; background: ${statusColor}; border-radius: 2px; transition: width 0.3s ease;"></div>
                  </div>
                  <div class="cat-budget-ceiling-text" style="font-size: 0.58rem; font-weight: 850; color: ${statusColor}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; line-height: 1.1; font-family: var(--font-numbers); direction: rtl;">
                    ${remainingText}
                  </div>
                `;
                lowerHalf.appendChild(newWrap);
              }
            } else {
              card.classList.remove('budget-pulse-alert');
              if (ceilingWrap) ceilingWrap.remove();
            }
          }
        });
      }
        const activeHomeLayoutNow = (window.HomeLayouts && typeof window.HomeLayouts.getLayout === 'function')
          ? window.HomeLayouts.getLayout()
          : (parseInt(localStorage.getItem('family_expense_home_design_v2'), 10) || 0);
        if (activeHomeLayoutNow > 0 && window.HomeLayouts && typeof window.HomeLayouts.render === 'function') {
          window.HomeLayouts.render(filtered);
        }
      } finally {
        isRenderingCategoryGrid = false;
      }
    }

