    function getRegisteredOperations(transactions = state.transactions || []) {
      let list = [...transactions];

      // 2. تطبيق فلترة الفترة الزمنية بدقة تامة (اليوم / الأسبوع / الشهر / السنة / الكل / مخصص)
      const p = state.period || 'month';
      const now = new Date();
      const todayStr = getLocalDateStr(now);

      if (monthlyExpenseViewModes.includes(state.opsViewMode)) {
        if (!expenseCalendar.month) {
          const customStart = p === 'custom' ? state.customDateRange?.from : '';
          expenseCalendar.month = /^\d{4}-(0[1-9]|1[0-2])-\d{2}$/.test(customStart || '') ?
            customStart.slice(0, 7) : todayStr.slice(0, 7);
        }
        list = list.filter(t => operationDate(t).slice(0, 7) === expenseCalendar.month);
      } else if (p === 'day' || p === 'today') {
        list = list.filter(t => operationDate(t) === todayStr);
      } else if (p === 'week') {
        const sevenDaysAgo = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
        const sevenDaysAgoStr = getLocalDateStr(sevenDaysAgo);
        list = list.filter(t => operationDate(t) >= sevenDaysAgoStr && operationDate(t) <= todayStr);
      } else if (p === 'month') {
        const curYearMonth = todayStr.slice(0, 7);
        list = list.filter(t => operationDate(t).startsWith(curYearMonth));
      } else if (p === 'year') {
        const curYear = todayStr.slice(0, 4);
        list = list.filter(t => operationDate(t).startsWith(curYear));
      } else if (p === 'custom' && state.customDateRange) {
        const { from, to } = state.customDateRange;
        if (from && to) {
          list = list.filter(t => operationDate(t) >= from && operationDate(t) <= to);
        } else if (from) {
          list = list.filter(t => operationDate(t) >= from);
        } else if (to) {
          list = list.filter(t => operationDate(t) && operationDate(t) <= to);
        }
      }

      // 3. تطبيق تصفية النوع على العمليات (المصروفات / الدخل / الكل)
      const operationType = ['timeline', ...monthlyExpenseViewModes].includes(state.opsViewMode) ? 'expense' : opsTypeFilterState;
      if (operationType === 'expense') {
        list = list.filter(t => t.type === 'expense');
      } else if (operationType === 'income') {
        list = list.filter(t => t.type === 'income');
      }


      const categories = new Set(getOperationFilterValues('opsFilterCategory'));
      const members = new Set(getOperationFilterValues('opsFilterMember'));
      const projects = new Set(getOperationFilterValues('opsFilterProject').map(project => project.toLocaleLowerCase()));
      const categoryAliases = {
        supermarket: 'food', shopping: 'food', cafe: 'daily', utilities: 'bills',
        fuel: 'transport', home: 'house', medical: 'health', pharmacy: 'health',
        school: 'education', others: 'other', gifts: 'other', kids: 'other',
        entertainment: 'other', charity: 'other', games: 'other', income: 'other_inc'
      };
      if (categories.size) {
        list = list.filter(transaction => {
          const category = String(transaction.category || '').toLowerCase();
          return categories.has(Object.hasOwn(categoryAliases, category) ? categoryAliases[category] : category);
        });
      }
      if (members.size) {
        list = list.filter(transaction => {
          const member = transaction.member || 'البيت';
          return members.has(member === 'العائلة' ? 'البيت' : member === 'أية' ? 'آية' : member);
        });
      }
      if (projects.size) {
        list = list.filter(transaction => {
          const project = getTransactionProjectName(transaction).toLocaleLowerCase();
          return projects.has(project || '__no_project__');
        });
      }
      if (state.currentWalletId && state.currentWalletId !== 'all') {
        list = list.filter(transaction => transaction.walletId === state.currentWalletId);
      }

      // 6. تطبيق نص البحث إذا وجد
      const searchInp = document.getElementById('opsSearchInput');
      const q = searchInp ? searchInp.value.trim().toLowerCase() : '';
      if (q) {
        list = list.filter(t => {
          const l = (t.label || t.description || t.note || '').toLowerCase();
          const c = (t.category || '').toLowerCase();
          const cName = (typeof getCategoryName === 'function' ? (getCategoryName(t.category, t.type) || '') : '').toLowerCase();
          const m = (t.member || '').toLowerCase();
          const a = String(t.amount || '');
          const w = (typeof getWalletName === 'function' ? getWalletName(t.walletId) : '').toLowerCase();
          const d = (t.date || '').toLowerCase();
          const project = getTransactionProjectName(t).toLowerCase();
          return l.includes(q) || c.includes(q) || cName.includes(q) || m.includes(q) || a.includes(q) || w.includes(q) || d.includes(q) || project.includes(q);
        });
      }

      return list;
    }

    function renderExpenseOperationRow({tx, minutes}, transactions) {
      const index = transactions.push(tx) - 1;
      const category = getCategoryObj(tx.category, 'expense');
      const icon = /^fa-[a-z0-9-]+$/i.test(category.icon) ? category.icon : 'fa-receipt';
      const time = minutes < 0 ? '' : (Math.floor(minutes / 60) % 12 || 12) + ':' +
        String(minutes % 60).padStart(2, '0') + (minutes >= 720 ? ' م' : ' ص');
      const memo = tx.label || tx.description || tx.note;
      const hasReceipt = tx.receipt || tx.receipts?.length;
      return `<details class="ops-timeline-item">
        <summary>
          <span class="ops-timeline-category"><i class="fa-solid ${icon}" aria-hidden="true"></i> <span>${escapeHtml(category.name)}</span></span>
          <span class="ops-timeline-time"><i class="fa-regular fa-clock" aria-hidden="true"></i> <bdi>${time || '—'}</bdi></span>
          <span class="ops-timeline-wallet"><i class="fa-solid fa-wallet" aria-hidden="true"></i> <span>${escapeHtml(getWalletName(tx.walletId))}</span></span>
          <bdi class="ops-timeline-money">${escapeHtml(formatMoney(tx.amount))}</bdi>
          <i class="fa-solid fa-chevron-left ops-timeline-chevron" aria-hidden="true"></i>
        </summary>
        <div class="ops-timeline-details">
          ${memo ? `<strong>${escapeHtml(memo)}</strong>` : ''}
          ${tx.member ? `<span>${escapeHtml(tx.member)}</span>` : ''}
          <div class="ops-timeline-actions">
            <button type="button" data-timeline-index="${index}" data-timeline-action="edit">تعديل</button>
            ${hasReceipt ? `<button type="button" data-timeline-index="${index}" data-timeline-action="receipt">المرفق</button>` : ''}
            <button type="button" data-timeline-index="${index}" data-timeline-action="delete">حذف</button>
          </div>
        </div>
      </details>`;
    }

    function timelineOperationMinutes(transaction) {
      const time = String(transaction.time || '').replace(/[٠-٩۰-۹]/g, digit => String(digit.charCodeAt(0) % 16));
      const match = time.match(/(\d{1,2}):([0-5]\d)(?::[0-5]\d)?/);
      if (match && Number(match[1]) < 24) {
        let hour = Number(match[1]);
        if (hour <= 12 && /(?:ص|م|am|pm)/i.test(time)) {
          hour = hour % 12 + (/(?:م|pm)/i.test(time) ? 12 : 0);
        }
        return hour * 60 + Number(match[2]);
      }
      const recorded = transaction.createdAt || (String(transaction.date || '').includes('T') ? transaction.date : '');
      const date = new Date(recorded);
      return Number.isFinite(date.getTime()) ? date.getHours() * 60 + date.getMinutes() : -1;
    }

    function renderDailyExpenseTimeline(list, limit) {
      const days = new Map();
      for (const transaction of list) {
        const raw = operationDate(transaction);
        const date = /^\d{4}-\d{2}-\d{2}$/.test(raw) && Number.isFinite(Date.parse(raw)) ? raw : '';
        if (!days.has(date)) days.set(date, {rows: [], sum: 0});
        const day = days.get(date);
        day.rows.push(transaction);
        day.sum += Number(transaction.amount) || 0;
      }
      const today = new Date();
      const todayKey = getLocalDateStr(today);
      today.setDate(today.getDate() - 1);
      const yesterdayKey = getLocalDateStr(today);
      const opts = {timeZone: 'UTC'};
      const fullDate = new Intl.DateTimeFormat('ar-EG', {...opts, dateStyle: 'full'});
      const weekDay = new Intl.DateTimeFormat('ar-EG', {...opts, weekday: 'long'});
      const month = new Intl.DateTimeFormat('ar-EG', {...opts, month: 'long'});
      let remaining = limit;
      let tone = 0;
      const groups = [];
      const renderedTransactions = [];
      for (const [date, day] of [...days].sort(([a], [b]) => b.localeCompare(a))) {
        if (remaining <= 0) break;
        const dayDate = new Date(date + 'T12:00:00Z');
        const marker = date === todayKey ? 'اليوم' : date === yesterdayKey ? 'أمس' : date ? weekDay.format(dayDate) : '—';
        const rows = day.rows.map(tx => ({tx, minutes: timelineOperationMinutes(tx)}))
          .sort((a,b) => b.minutes - a.minutes).slice(0,remaining);
        remaining -= rows.length;
        const lineItems = rows.map(row => renderExpenseOperationRow(row, renderedTransactions)).join('');
        groups.push(`<section class="ops-timeline-day" data-tone="${tone++ % 5}" data-date="${date}">
          <div class="ops-timeline-marker" aria-hidden="true"><small>${marker}</small><strong>${date ? Number(date.slice(-2)) : '—'}</strong><small>${date ? month.format(dayDate) : ''}</small></div>
          <div class="ops-timeline-card">
            <header><h4>${date ? fullDate.format(dayDate) : 'مصروفات بلا تاريخ'}</h4>
              <span>إجمالي اليوم <bdi>${escapeHtml(formatMoney(day.sum))}</bdi></span></header>
            ${lineItems}
          </div>
        </section>`);
      }
      return {html: '<div class="ops-timeline"><h3><i class="fa-regular fa-calendar" aria-hidden="true"></i> تسلسل يومي</h3>' +
        groups.join('') + '</div>', transactions: renderedTransactions};
    }

    const expenseCalendar = {month: '', date: ''};
    const expenseCalendarMonthLabel = new Intl.DateTimeFormat('ar-EG', {
      month: 'long', year: 'numeric', timeZone: 'UTC'
    });
    const expenseCalendarDateLabel = new Intl.DateTimeFormat('ar-EG', {
      dateStyle: 'full', timeZone: 'UTC'
    });

    function changeExpenseCalendarMonth(step) {
      const month = new Date(expenseCalendar.month + '-01T12:00:00Z');
      month.setUTCMonth(month.getUTCMonth() + step);
      expenseCalendar.month = month.toISOString().slice(0, 7);
      expenseCalendar.date = '';
    }

    function renderExpenseCalendarGrid(month, days, offset, byDate, selectedDate, now) {
      const padding = '<span class="ops-calendar-blank" aria-hidden="true"></span>';
      const cells = Array(offset).fill(padding);
      for (let number = 1; number <= days; number++) {
        const date = month + '-' + String(number).padStart(2, '0');
        const day = byDate.get(date);
        const amount = day ? formatMoney(day.sum) : '';
        const label = expenseCalendarDateLabel.format(new Date(date + 'T12:00:00Z'));
        cells.push(`<button type="button" class="ops-calendar-day${day ? ' has-expenses' : ''}"
          data-calendar-date="${date}" aria-pressed="${date === selectedDate}"
          ${date === now ? 'aria-current="date"' : ''}
          aria-label="${escapeHtml(label + '، ' + (amount || 'لا توجد مصروفات'))}">
            <span>${number}</span><bdi>${amount ? escapeHtml(amount) : '–'}</bdi>
          </button>`);
      }
      while (cells.length % 7) cells.push(padding);
      const week = ['السبت', 'الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة'];
      return `<div class="ops-calendar-grid">
        ${week.map(day => `<span class="ops-calendar-weekday">${day}</span>`).join('')}
        ${cells.join('')}
      </div>`;
    }

    function renderMonthlyExpenseTrend(month, days, byDate, selectedDate) {
      const bounds = {left: 41, right: 351, top: 17, bottom: 116};
      const dayWidth = (bounds.right - bounds.left) / days;
      const points = Array.from({length: days}, (_, index) => {
        const day = index + 1;
        const date = month + '-' + String(day).padStart(2, '0');
        return {day, date, amount: byDate.get(date)?.sum || 0, x: bounds.left + dayWidth * (index + 0.5)};
      });
      const totals = points.map(point => point.amount);
      const peak = Math.max(0, ...totals);
      const floor = Math.min(0, ...totals);
      const target = Math.max(1, (peak - floor) / 4);
      const magnitude = 10 ** Math.floor(Math.log10(target));
      const interval = magnitude * [1,2,2.5,5,10].find(step => step * magnitude >= target);
      const min = Math.floor(floor / interval) * interval;
      const intervals = Math.max(4, Math.ceil((peak - min) / interval));
      const compact = new Intl.NumberFormat('en', {notation: 'compact', maximumFractionDigits: 1});
      const y = amount => (bounds.bottom - (amount - min) / (interval * intervals) * (bounds.bottom - bounds.top)).toFixed(2);
      const coordinates = points.map(point => point.x.toFixed(2) + ',' + y(point.amount)).join(' ');
      const last = points.at(-1);
      const basePath = `M ${points[0].x.toFixed(2)},${y(0)} L ${coordinates} L ${last.x.toFixed(2)},${y(0)} Z`;
      const grid = Array.from({length: intervals + 1}, (_, i) => {
        const amount = min + i * interval;
        const lineY = y(amount);
        return `<line x1="${bounds.left}" x2="${bounds.right}" y1="${lineY}" y2="${lineY}"/>
          <text x="${bounds.left - 6}" y="${lineY}" dominant-baseline="middle" text-anchor="end">${compact.format(amount)}</text>`;
      }).join('');
      const xLabels = points.filter(point => point.day === 1 || point.day === days ||
        (point.day % 5 === 0 && days - point.day > 2))
        .map(point => `<text x="${point.x.toFixed(2)}" y="136" text-anchor="middle">${point.day}</text>`).join('');
      const controls = points.map(point => {
        const active = point.date === selectedDate;
        const label = expenseCalendarDateLabel.format(new Date(point.date + 'T12:00:00Z')) +
          '، ' + formatMoney(point.amount);
        return `<g class="ops-month-trend-point" role="button" tabindex="${active ? 0 : -1}"
          aria-pressed="${active}" aria-label="${escapeHtml(label)}" data-calendar-date="${point.date}">
          <rect x="${(point.x - dayWidth / 2).toFixed(2)}" y="${bounds.top - 8}" width="${dayWidth.toFixed(2)}" height="125"/>
          <circle cx="${point.x.toFixed(2)}" cy="${y(point.amount)}" r="${active ? 4.1 : 2.3}"/>
        </g>`;
      }).join('');
      const selected = points.find(point => point.date === selectedDate);
      const amountLabel = formatMoney(selected.amount);
      const labelWidth = Math.min(142, Math.max(50, amountLabel.length * 6.4 + 12));
      const labelX = Math.max(bounds.left, Math.min(bounds.right - labelWidth, selected.x - labelWidth / 2));
      const pointY = Number(y(selected.amount));
      const labelY = pointY < 27 ? pointY + 8 : pointY - 24;
      return `<svg class="ops-month-trend" viewBox="0 0 360 145" role="group"
        aria-label="إجمالي المصروفات لكل يوم، استخدم السهمين للتنقل بين الأيام">
        <defs><linearGradient id="opsMonthTrendFill" x2="0" y2="1">
          <stop offset="0" stop-color="currentColor" stop-opacity=".34"/>
          <stop offset="1" stop-color="currentColor" stop-opacity=".02"/>
        </linearGradient></defs>
        <g class="ops-month-trend-grid" aria-hidden="true">${grid}${xLabels}</g>
        <path d="${basePath}" fill="url(#opsMonthTrendFill)" aria-hidden="true"/>
        <polyline class="ops-month-trend-line" points="${coordinates}" aria-hidden="true"/>
        ${controls}
        <g class="ops-month-trend-label" aria-hidden="true">
          <rect x="${labelX}" y="${labelY}" width="${labelWidth}" height="16" rx="5"/>
          <text x="${labelX + labelWidth / 2}" y="${labelY + 8.3}" dominant-baseline="middle"
            text-anchor="middle">${escapeHtml(amountLabel)}</text>
        </g>
      </svg>`;
    }

    function renderMonthlyExpenses(list, limit, showTrend) {
      const now = getLocalDateStr(new Date());
      const monthKey = expenseCalendar.month;
      const first = new Date(monthKey + '-01T12:00:00Z');
      const days = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + 1, 0)).getUTCDate();
      const byDate = new Map();
      let monthTotal = 0;
      for (const tx of list) {
        const date = operationDate(tx);
        const number = Number(date.slice(8));
        if (!Number.isInteger(number) || number < 1 || number > days) continue;
        if (!byDate.has(date)) byDate.set(date, {sum: 0, rows: []});
        const day = byDate.get(date);
        const amount = Number(tx.amount) || 0;
        day.sum += amount;
        monthTotal += amount;
        day.rows.push(tx);
      }
      if (!expenseCalendar.date.startsWith(monthKey + '-')) {
        expenseCalendar.date = now.startsWith(monthKey + '-') ? now :
          [...byDate.keys()].sort().at(-1) || monthKey + '-01';
      }
      const selectedDate = expenseCalendar.date;
      const selected = byDate.get(selectedDate);
      const chart = showTrend ? renderMonthlyExpenseTrend(monthKey, days, byDate, selectedDate) :
        renderExpenseCalendarGrid(monthKey, days, (first.getUTCDay() + 1) % 7, byDate, selectedDate, now);
      const title = showTrend ? 'مسار المصروفات خلال الشهر' : 'تقويم المصروفات';
      const icon = showTrend ? 'fa-solid fa-chart-line' : 'fa-regular fa-calendar';
      const transactions = [];
      const rows = selected ? selected.rows.map(tx => ({tx, minutes: timelineOperationMinutes(tx)}))
        .sort((a,b) => b.minutes - a.minutes).slice(0, limit) : [];
      const dayLabel = expenseCalendarDateLabel.format(new Date(selectedDate + 'T12:00:00Z'));
      const html = `<section class="ops-calendar" aria-label="${title}">
        <header class="ops-calendar-header">
          <h3><i class="${icon}" aria-hidden="true"></i> ${title}</h3>
          <div class="ops-calendar-navigation">
            <button type="button" data-calendar-step="-1" aria-label="الشهر السابق"><span dir="ltr" aria-hidden="true">›</span></button>
            <strong aria-live="polite">${expenseCalendarMonthLabel.format(first)}</strong>
            <button type="button" data-calendar-step="1" aria-label="الشهر التالي"><span dir="ltr" aria-hidden="true">‹</span></button>
          </div>
        </header>
        ${chart}
        <p class="ops-calendar-month-total">إجمالي الشهر <bdi>${escapeHtml(formatMoney(monthTotal))}</bdi></p>
        <section class="ops-calendar-selection" aria-label="مصروفات اليوم المختار">
          <header${showTrend ? ' class="ops-month-trend-detail"' : ''}><h4>${dayLabel}</h4>${showTrend || selected ? `<span>إجمالي اليوم <bdi>${escapeHtml(formatMoney(selected?.sum || 0))}</bdi></span>` : ''}</header>
          ${selected ? rows.map(row => renderExpenseOperationRow(row, transactions)).join('') :
            '<p class="ops-calendar-empty">لا توجد مصروفات مطابقة في هذا اليوم.</p>'}
        </section>
      </section>`;
      return {html, transactions, remaining: Math.max(0, (selected?.rows.length || 0) - limit)};
    }

    function renderOperationsList(filtered, appendMore = false) {
      const container = document.getElementById('txOperationsList');
      if (!container) return;
      if (!operationsViewModes.includes(state.opsViewMode)) state.opsViewMode = 'daily';
      const curOpsMode = state.opsViewMode;
      const monthlyExpenseLayout = monthlyExpenseViewModes.includes(curOpsMode);
      const expenseLayout = curOpsMode === 'timeline' || monthlyExpenseLayout;
      const opsView = document.getElementById('viewOperations');
      opsView.classList.toggle('has-expense-layout', expenseLayout);
      opsView.classList.toggle('is-monthly-expense-layout', monthlyExpenseLayout);
      for (const button of document.querySelectorAll('#opsViewModeToggleBar [data-view-mode]')) {
        const active = button.dataset.viewMode === curOpsMode;
        button.classList.toggle('active', active);
        button.setAttribute('aria-pressed', String(active));
      }
      refreshProjectSelectors();
      if (!appendMore) opsRenderLimit = 40;
      const list = getRegisteredOperations(filtered ?? undefined);
      document.getElementById('opsResultCount').textContent = list.length.toLocaleString('ar-EG') + ' عملية مطابقة';

      if (list.length === 0 && !monthlyExpenseLayout) {
        container.innerHTML = `
          <div class="empty-state" style="padding: 30px 10px; text-align: center;">
            <i class="fa-solid fa-receipt" style="color: #64748b; font-size: 2.2rem; margin-bottom: 10px;"></i>
            <div class="empty-title" style="color: #cbd5e1; font-weight: 800; font-size: 0.95rem;">لا توجد عمليات مطابقة للفترة أو الفلاتر</div>
            <div class="empty-desc" style="color: #64748b; font-size: 0.8rem; margin-top: 4px;">جرّب اختيار فترة زمنية أخرى (الشهر / الكل) أو إعادة ضبط الفلاتر</div>
          </div>
        `;
        return;
      }

      const todayIso = getLocalDateStr(new Date());
      const yesterdayDate = new Date();
      yesterdayDate.setDate(yesterdayDate.getDate() - 1);
      const yesterdayIso = getLocalDateStr(yesterdayDate);

      // ترتيب الحركات تنازلياً حسب التاريخ والوقت
      list.sort((a, b) => {
        const da = (a.date || '') + ' ' + (a.time || '');
        const db = (b.date || '') + ' ' + (b.time || '');
        return db.localeCompare(da);
      });

      const itemsToRender = list.slice(0, opsRenderLimit);
      let cardsHtml = '';
      let expenseView;

      if (expenseLayout) {
        expenseView = curOpsMode === 'timeline' ?
          renderDailyExpenseTimeline(list, opsRenderLimit) : renderMonthlyExpenses(list, opsRenderLimit, curOpsMode === 'month-trend');
        cardsHtml = expenseView.html;
      } else if (curOpsMode === 'flat') {
        // =========================================================================
        // الوضع الجديد: "مجمع" (بدون تجميع لعمليات اليوم + التاريخ مدمج أسفل بيان العملية)
        // =========================================================================
        itemsToRender.forEach(tx => {
          const cat = getCategoryObj(tx.category, tx.type);
          const isExp = tx.type === 'expense';
          const amt = Number(tx.amount) || 0;
          const sign = isExp ? '-' : '+';
          const memberName = tx.member || 'العائلة';
          const walletName = typeof getWalletName === 'function' ? getWalletName(tx.walletId) : '';
          const projectName = getTransactionProjectName(tx);
          const isSelected = (window.selectedOperationRowId === tx.id);
          let cleanLbl = (tx.label || tx.description || tx.note || '').trim();
          if (!cleanLbl || cleanLbl === 'بيان' || cleanLbl === 'بدون بيان') {
            cleanLbl = `${cat.name} (${memberName})`;
          }
          const rawLabel = cleanLbl;
          const date = operationDate(tx);
          const isLight = document.body.classList.contains('light-theme') || document.documentElement.getAttribute('data-app-theme') === 'light';
          const harm = typeof getHarmonizedCategoryColor === 'function' ? getHarmonizedCategoryColor(cat.color, isLight) : { color: '#38bdf8', bg: 'rgba(56,189,248,0.15)', border: 'rgba(56,189,248,0.4)', badgeBorder: 'rgba(56,189,248,0.3)' };

          cardsHtml += `
            <div class="ops-tx-card-clean ${isSelected ? 'is-selected' : ''}" data-tx-id="${tx.id}" onclick="toggleSelectOperationRow('${tx.id}')" style="border-right: 3.5px solid ${harm.color} !important; cursor: pointer; padding: 6px 10px; margin-bottom: 5px; border-radius: 10px;">
              <div class="ops-entry-compact" style="display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%;">
                <div style="display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0;">
                  <span class="ops-compact-icon" style="width: 32px; height: 32px; min-width: 32px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 0.85rem; background: ${harm.bg} !important; border: 1px solid ${harm.border} !important; color: ${harm.color} !important;" aria-hidden="true">
                    <i class="fa-solid ${cat.icon || 'fa-receipt'}"></i>
                  </span>
                  <div style="display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1;">
                    <div style="display: flex; align-items: center; gap: 6px; min-width: 0;">
                      <span class="ops-compact-title" style="font-size: 0.82rem; font-weight: 850; color: var(--text-main, #0f172a); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.2;">${escapeHtml(rawLabel)}</span>
                      ${tx.isModified ? `<span style="background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.35); border-radius: 4px; padding: 0.5px 3px; font-size: 0.55rem; font-weight: 800; flex-shrink: 0;" title="تم التعديل بواسطة ${escapeHtml(tx.lastModifiedBy || '')} - السبب: ${escapeHtml(tx.lastModifiedReason || '')}">✏️</span>` : ''}
                    </div>
                    <div class="ops-compact-chips">
                      <span style="color: ${harm.color}; border: 1px solid ${harm.badgeBorder}; background: ${harm.bg}; padding: 0.5px 5px; border-radius: 4px; font-weight: 800;">${escapeHtml(cat.name)}</span>
                      <span style="color: #64748b; background: rgba(100, 116, 139, 0.08); border: 1px solid rgba(100, 116, 139, 0.2); padding: 0.5px 5px; border-radius: 4px; font-weight: 750;">👤 ${escapeHtml(memberName)}</span>
                      ${walletName ? `<span style="color: #0284c7; background: rgba(2, 132, 199, 0.08); border: 1px solid rgba(2, 132, 199, 0.2); padding: 0.5px 5px; border-radius: 4px; font-weight: 750;">💳 ${escapeHtml(walletName)}</span>` : ''}
                      <span class="ops-compact-serial" style="font-family: monospace; font-size: 0.58rem; font-weight: 800; color: #64748b; background: rgba(100, 116, 139, 0.10); border: 1px solid rgba(100, 116, 139, 0.22); border-radius: 4px; padding: 0.5px 4px; direction: ltr; flex-shrink: 0; line-height: 1.2;">#${escapeHtml(tx.serialNo || tx.id)}</span>
                      ${projectName ? `<span style="color: #8b5cf6; background: rgba(139, 92, 246, 0.08); border: 1px solid rgba(139, 92, 246, 0.2); padding: 0.5px 5px; border-radius: 4px; font-weight: 750;">📌 ${escapeHtml(projectName)}</span>` : ''}
                      ${(tx.receipt || (tx.receipts && tx.receipts.length)) ? `<span onclick="event.stopPropagation(); openReceiptLightbox('${tx.id}')" style="cursor: pointer; color: #ec4899; background: rgba(236, 72, 153, 0.12); border: 1px solid rgba(236, 72, 153, 0.3); padding: 0.5px 6px; border-radius: 4px; font-weight: 800; display: inline-flex; align-items: center; gap: 3px;" title="عرض المرفقات المصورة"><i class="fa-solid fa-images"></i> ${(tx.receipts && tx.receipts.length > 1) ? tx.receipts.length + ' صور' : 'مرفق'}</span>` : ''}
                    </div>
                  </div>
                </div>
                <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 1px; flex-shrink: 0; text-align: left;">
                  <div style="font-size: 0.88rem; font-weight: 900; font-family: var(--font-numbers); direction: ltr; unicode-bidi: isolate; color: ${isExp ? '#dc2626' : '#059669'}; white-space: nowrap; line-height: 1.2; display: inline-flex; align-items: baseline; gap: 3px;">
                    <span style="font-size: 0.70rem; opacity: 0.85; font-weight: 800;">${typeof getCurrencySymbol === 'function' ? getCurrencySymbol() : (state.currency || 'ج.م')}</span>
                    <span>${sign} ${formatNumberValOnly(amt)}</span>
                  </div>
                  <div style="font-size: 0.62rem; color: #94a3b8; font-family: var(--font-numbers); direction: ltr; font-weight: 700; white-space: nowrap;">
                    ${escapeHtml(date || (tx.time || ''))}
                  </div>
                </div>
              </div>
              <!-- درج الإجراءات المخفي: يفتح حصرياً عند الضغط على العملية (تعديل، حذف، إيصال) -->
              <div class="ops-row-actions-drawer" data-drawer-tx-id="${tx.id}" style="display: ${isSelected ? 'flex' : 'none'}; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 255, 255, 0.12); animation: fadeIn 0.15s ease;">
                ${tx.receipt ? `
                  <button type="button" onclick="event.stopPropagation(); openReceiptLightbox('${tx.id}')" style="height: 30px; padding: 0 10px; border-radius: 8px; font-size: 0.72rem; font-weight: 800; background: rgba(236, 72, 153, 0.18); border: 1px solid rgba(236, 72, 153, 0.4); color: #f472b6; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;">
                    <i class="fa-solid fa-images"></i>
                    <span>عرض المرفقات ${(tx.receipts && tx.receipts.length > 1) ? `(${tx.receipts.length})` : ''}</span>
                  </button>
                ` : ''}
                <button type="button" onclick="event.stopPropagation(); editTx('${tx.id}')" style="height: 30px; padding: 0 12px; border-radius: 8px; font-size: 0.72rem; font-weight: 800; background: rgba(56, 189, 248, 0.18); border: 1px solid rgba(56, 189, 248, 0.4); color: #38bdf8; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;">
                  <i class="fa-solid fa-pen-to-square"></i>
                  <span>تعديل</span>
                </button>
                <button type="button" onclick="event.stopPropagation(); deleteTx('${tx.id}')" style="height: 30px; padding: 0 12px; border-radius: 8px; font-size: 0.72rem; font-weight: 800; background: rgba(244, 63, 94, 0.18); border: 1px solid rgba(244, 63, 94, 0.4); color: #f43f5e; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;">
                  <i class="fa-solid fa-trash-can"></i>
                  <span>حذف</span>
                </button>
              </div>

            </div>
          `;
        });
      } else {
        // =========================================================================
        // الوضع الحالي: "تجميع باليوم" (المجمّع بحسب التاريخ مع الترويسات والإجماليات)
        // =========================================================================
        const groupedByDate = Object.create(null);
        itemsToRender.forEach(tx => {
          const d = curOpsMode === 'project'
            ? (getTransactionProjectName(tx) || 'بدون مشروع')
            : (tx.date || todayIso);
          if (!groupedByDate[d]) groupedByDate[d] = [];
          groupedByDate[d].push(tx);
        });

        // بناء مخرجات البطاقات ككتلة HTML موحدة وسريعة جداً
        for (const [dateStr, txs] of Object.entries(groupedByDate)) {
          let groupTitle = dateStr;
          if (curOpsMode === 'project') groupTitle = `📌 المشروع: ${dateStr}`;
          else if (dateStr === todayIso) groupTitle = 'اليوم (Today) - ' + dateStr;
          else if (dateStr === yesterdayIso) groupTitle = 'الأمس (Yesterday) - ' + dateStr;

          let dayExpSum = 0, dayIncSum = 0;
          txs.forEach(t => {
            const amt = Number(t.amount) || 0;
            if (t.type === 'expense') dayExpSum += amt;
            else dayIncSum += amt;
          });

          let subtotalBadge = '';
          if (dayExpSum > 0 && dayIncSum > 0) {
            subtotalBadge = `${formatMoneyWithSignHtml(dayExpSum, '-', 'ops-date-subtotal exp')} ${formatMoneyWithSignHtml(dayIncSum, '+', 'ops-date-subtotal inc')}`;
          } else if (dayExpSum > 0) {
            subtotalBadge = `<span style="font-size: 0.70rem; color: #94a3b8; margin-left: 3px;">إجمالي المنصرف:</span> ${formatMoneyWithSignHtml(dayExpSum, '-', 'ops-date-subtotal exp')}`;
          } else {
            subtotalBadge = `<span style="font-size: 0.70rem; color: #94a3b8; margin-left: 3px;">إجمالي الدخل:</span> ${formatMoneyWithSignHtml(dayIncSum, '+', 'ops-date-subtotal inc')}`;
          }

          cardsHtml += `
            <div class="ops-date-group-header">
              <div class="ops-date-title"><i class="${curOpsMode === 'project' ? 'fa-solid fa-folder-tree' : 'fa-regular fa-calendar'}"></i> ${escapeHtml(groupTitle)}</div>
              <div>${subtotalBadge}</div>
            </div>
          `;

          // بناء بطاقة الحركة النظيفة (العملية، البيان، الرقم، التاريخ فقط)
          txs.forEach(tx => {
            const cat = getCategoryObj(tx.category, tx.type);
            const isExp = tx.type === 'expense';
            const amt = Number(tx.amount) || 0;
            const sign = isExp ? '-' : '+';
              const memberName = tx.member || 'العائلة';
            const walletName = typeof getWalletName === 'function' ? getWalletName(tx.walletId) : '';
            const projectName = getTransactionProjectName(tx);
            const isSelected = (window.selectedOperationRowId === tx.id);
            let cleanLbl = (tx.label || tx.description || tx.note || '').trim();
            if (!cleanLbl || cleanLbl === 'بيان' || cleanLbl === 'بدون بيان') {
              cleanLbl = `${cat.name} (${memberName})`;
            }
            const rawLabel = cleanLbl;

            const isLightFlat = document.body.classList.contains('light-theme') || document.documentElement.getAttribute('data-app-theme') === 'light';
            const harmFlat = typeof getHarmonizedCategoryColor === 'function' ? getHarmonizedCategoryColor(cat.color, isLightFlat) : { color: '#38bdf8', bg: 'rgba(56,189,248,0.15)', border: 'rgba(56,189,248,0.4)', badgeBorder: 'rgba(56,189,248,0.3)' };

            cardsHtml += `
              <div class="ops-tx-card-clean ${isSelected ? 'is-selected' : ''}" data-tx-id="${tx.id}" onclick="toggleSelectOperationRow('${tx.id}')" style="border-right: 3.5px solid ${harmFlat.color} !important; cursor: pointer; padding: 6px 10px; margin-bottom: 5px; border-radius: 10px;">
              <div class="ops-entry-compact" style="display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%;">
                <!-- الجانب الأيمن: الأيقونة + العنوان والسريال والرقائق في سطرين مدمجين -->
                <div style="display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0;">
                  <span class="ops-compact-icon" style="width: 32px; height: 32px; min-width: 32px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 0.85rem; background: ${harmFlat.bg} !important; border: 1px solid ${harmFlat.border} !important; color: ${harmFlat.color} !important;" aria-hidden="true">
                    <i class="fa-solid ${cat.icon || 'fa-receipt'}"></i>
                  </span>
                  <div style="display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1;">
                    <!-- السطر الأول: العنوان ومعه شارة السريال المدمجة الأنيقة -->
                    <div style="display: flex; align-items: center; gap: 6px; min-width: 0;">
                      <span class="ops-compact-title" style="font-size: 0.82rem; font-weight: 850; color: var(--text-main, #0f172a); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.2;">${escapeHtml(rawLabel)}</span>
                      ${tx.isModified ? `<span style="background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.35); border-radius: 4px; padding: 0.5px 3px; font-size: 0.55rem; font-weight: 800; flex-shrink: 0;" title="تم التعديل بواسطة ${escapeHtml(tx.lastModifiedBy || '')} - السبب: ${escapeHtml(tx.lastModifiedReason || '')}">✏️</span>` : ''}
                    </div>
                    <!-- السطر الثاني: رقائق مدمجة وبجانب المحفظة رقم العملية مباشرة -->
                    <div class="ops-compact-chips">
                      <span style="color: ${harmFlat.color}; border: 1px solid ${harmFlat.badgeBorder}; background: ${harmFlat.bg}; padding: 0.5px 5px; border-radius: 4px; font-weight: 800;">${escapeHtml(cat.name)}</span>
                      <span style="color: #64748b; background: rgba(100, 116, 139, 0.08); border: 1px solid rgba(100, 116, 139, 0.2); padding: 0.5px 5px; border-radius: 4px; font-weight: 750;">👤 ${escapeHtml(memberName)}</span>
                      ${walletName ? `<span style="color: #0284c7; background: rgba(2, 132, 199, 0.08); border: 1px solid rgba(2, 132, 199, 0.2); padding: 0.5px 5px; border-radius: 4px; font-weight: 750;">💳 ${escapeHtml(walletName)}</span>` : ''}
                      <span class="ops-compact-serial" style="font-family: monospace; font-size: 0.58rem; font-weight: 800; color: #64748b; background: rgba(100, 116, 139, 0.10); border: 1px solid rgba(100, 116, 139, 0.22); border-radius: 4px; padding: 0.5px 4px; direction: ltr; flex-shrink: 0; line-height: 1.2;">#${escapeHtml(tx.serialNo || tx.id)}</span>
                      ${projectName ? `<span style="color: #8b5cf6; background: rgba(139, 92, 246, 0.08); border: 1px solid rgba(139, 92, 246, 0.2); padding: 0.5px 5px; border-radius: 4px; font-weight: 750;">📌 ${escapeHtml(projectName)}</span>` : ''}
                      ${(tx.receipt || (tx.receipts && tx.receipts.length)) ? `<span onclick="event.stopPropagation(); openReceiptLightbox('${tx.id}')" style="cursor: pointer; color: #ec4899; background: rgba(236, 72, 153, 0.12); border: 1px solid rgba(236, 72, 153, 0.3); padding: 0.5px 6px; border-radius: 4px; font-weight: 800; display: inline-flex; align-items: center; gap: 3px;" title="عرض المرفقات المصورة"><i class="fa-solid fa-images"></i> ${(tx.receipts && tx.receipts.length > 1) ? tx.receipts.length + ' صور' : 'مرفق'}</span>` : ''}
                    </div>
                  </div>
                </div>
                <!-- الجانب الأيسر: المبلغ والتاريخ/الوقت -->
                <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 1px; flex-shrink: 0; text-align: left;">
                  <div style="font-size: 0.88rem; font-weight: 900; font-family: var(--font-numbers); direction: ltr; unicode-bidi: isolate; color: ${isExp ? '#dc2626' : '#059669'}; white-space: nowrap; line-height: 1.2; display: inline-flex; align-items: baseline; gap: 3px;">
                    <span style="font-size: 0.70rem; opacity: 0.85; font-weight: 800;">${typeof getCurrencySymbol === 'function' ? getCurrencySymbol() : (state.currency || 'ج.م')}</span>
                    <span>${sign} ${formatNumberValOnly(amt)}</span>
                  </div>
                  <div style="font-size: 0.62rem; color: #94a3b8; font-family: var(--font-numbers); direction: ltr; font-weight: 700; white-space: nowrap;">
                    ${escapeHtml(tx.time || (operationDate(tx) || ''))}
                  </div>
                </div>
              </div>
              <!-- درج الإجراءات المخفي: يفتح حصرياً عند الضغط على العملية (تعديل، حذف، إيصال) -->
                <div class="ops-row-actions-drawer" data-drawer-tx-id="${tx.id}" style="display: ${isSelected ? 'flex' : 'none'}; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 255, 255, 0.12); animation: fadeIn 0.15s ease;">
                  ${tx.receipt ? `
                    <button type="button" onclick="event.stopPropagation(); openReceiptLightbox('${tx.id}')" style="height: 30px; padding: 0 10px; border-radius: 8px; font-size: 0.72rem; font-weight: 800; background: rgba(236, 72, 153, 0.18); border: 1px solid rgba(236, 72, 153, 0.4); color: #f472b6; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;">
                      <i class="fa-solid fa-images"></i>
                      <span>عرض المرفقات ${(tx.receipts && tx.receipts.length > 1) ? `(${tx.receipts.length})` : ''}</span>
                    </button>
                  ` : ''}
                  <button type="button" onclick="event.stopPropagation(); editTx('${tx.id}')" style="height: 30px; padding: 0 12px; border-radius: 8px; font-size: 0.72rem; font-weight: 800; background: rgba(56, 189, 248, 0.18); border: 1px solid rgba(56, 189, 248, 0.4); color: #38bdf8; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;">
                    <i class="fa-solid fa-pen-to-square"></i>
                    <span>تعديل</span>
                  </button>
                  <button type="button" onclick="event.stopPropagation(); deleteTx('${tx.id}')" style="height: 30px; padding: 0 12px; border-radius: 8px; font-size: 0.72rem; font-weight: 800; background: rgba(244, 63, 94, 0.18); border: 1px solid rgba(244, 63, 94, 0.4); color: #f43f5e; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;">
                    <i class="fa-solid fa-trash-can"></i>
                    <span>حذف</span>
                  </button>
                </div>

              </div>
            `;
          });
        }
      }

      const remaining = expenseView?.remaining ?? list.length - opsRenderLimit;
      if (remaining > 0) {
        cardsHtml += `
          <div style="text-align: center; margin: 15px 0 10px 0;">
            <button type="button" onclick="loadMoreOperations()" style="height: 36px; padding: 0 20px; border-radius: 10px; background: rgba(56, 189, 248, 0.15); border: 1.2px solid rgba(56, 189, 248, 0.35); color: #38bdf8; font-size: 0.78rem; font-weight: 850; cursor: pointer;">
              عرض المزيد من العمليات (${remaining} متبقية)
            </button>
          </div>
        `;
      }

      container.innerHTML = cardsHtml;
      if (expenseView) {
        const view = container.firstElementChild;
        function showExpenseDay(date) {
          expenseCalendar.date = date;
          renderOperationsList(filtered);
          container.querySelector(`[data-calendar-date="${date}"]`)?.focus({preventScroll: true});
        }
        view.addEventListener('click', event => {
          const action = event.target.closest('button, [data-calendar-date]');
          if (!action) return;
          const {timelineAction, timelineIndex, calendarDate, calendarStep} = action.dataset;
          if (timelineAction) {
            const tx = expenseView.transactions[Number(timelineIndex)];
            if (!tx) return;
            if (timelineAction === 'edit') editTx(tx.id);
            else if (timelineAction === 'receipt') openReceiptLightbox(tx.id);
            else if (timelineAction === 'delete') deleteTx(tx.id);
          } else if (calendarStep) {
            changeExpenseCalendarMonth(Number(calendarStep));
            renderOperationsList(filtered);
            container.querySelector(`[data-calendar-step="${calendarStep}"]`)?.focus({preventScroll: true});
          } else if (calendarDate) {
            showExpenseDay(calendarDate);
          }
        });
        if (curOpsMode === 'month-trend') {
          view.addEventListener('keydown', event => {
            const point = event.target.closest('.ops-month-trend-point');
            if (!point || !['ArrowLeft','ArrowRight','Enter',' '].includes(event.key)) return;
            event.preventDefault();
            const target = event.key === 'ArrowLeft' ? point.previousElementSibling :
              event.key === 'ArrowRight' ? point.nextElementSibling : point;
            if (target?.dataset.calendarDate) showExpenseDay(target.dataset.calendarDate);
          });
        }
      }
    }
function loadMoreOperations() {
      opsRenderLimit = (opsRenderLimit || 40) + 40;
      renderOperationsList(null, true);
    }

    function filterOperationsList() {
      const inp = document.getElementById('opsSearchInput');
      state.searchQuery = inp ? inp.value.trim() : '';
      renderOperationsList(state.transactions || []);
    }

    function resetOperationsFilters() {
      if (typeof clearIndicatorsReturnBanner === 'function') clearIndicatorsReturnBanner();
      // 1. مسح حقل البحث
      const inp = document.getElementById('opsSearchInput');
      if (inp) inp.value = '';
      state.searchQuery = '';

      // 2. تصفير منتقيات الفلترة المتقدمة (البنود، الأفراد، المشاريع)
      ['opsFilterCategory', 'opsFilterMember', 'opsFilterProject'].forEach(id => {
        if (typeof setOperationFilterValues === 'function') {
          setOperationFilterValues(id, []);
        }
      });
      // إغلاق أي تفاصيل منسدلة مفتوحة
      document.querySelectorAll('.ops-picker[open]').forEach(p => { p.open = false; });

      // 3. إعادة ضبط نوع العملية لكافة العمليات
      opsTypeFilterState = 'all';
      const pillBox = document.getElementById('opsTypeFilterPills');
      if (pillBox) {
        pillBox.querySelectorAll('.btn-export-tool').forEach(b => {
          b.classList.remove('active');
          b.style.background = 'transparent';
          b.style.color = '#94a3b8';
        });
        const btnAll = document.getElementById('btnOpsFilterAll');
        if (btnAll) {
          btnAll.classList.add('active');
          btnAll.style.background = 'rgba(56, 189, 248, 0.25)';
          btnAll.style.color = '#38bdf8';
        }
      }

      // 4. إعادة ضبط فلتر المشاريع والأفراد العام
      state.projectFilter = 'all';
      if (typeof refreshProjectSelectors === 'function') refreshProjectSelectors();

      // 5. Clear all remaining dimensions; "clear filters" must show all history.
      state.customDateRange = null;
      state.currentWalletId = 'all';
      const walletSelector = document.getElementById('activeWalletSelect');
      if (walletSelector) walletSelector.value = 'all';
      state.currentMemberFilter = 'الكل';
      state.selectedMember = 'الكل';
      if (typeof setAppPeriod === 'function') {
        setAppPeriod('all', false);
      } else {
        state.period = 'all';
      }

      // 6. تحديث قائمة العمليات المسجلة فوراً
      if (typeof filterOperationsList === 'function') {
        filterOperationsList();
      } else if (typeof renderOperationsList === 'function') {
        renderOperationsList(state.transactions || []);
      }

      if (typeof showToast === 'function') {
        showToast('🧹 تم مسح كافة الفلاتر بنجاح وعرض كافة العمليات');
      }
    }
    window.resetOperationsFilters = resetOperationsFilters;

    // =========================================================================
    // اختيار أفراد العائلة (Persistent Filter Across All Pages)
    // =========================================================================
    function selectMember(member) {
      state.currentMemberFilter = member;
      state.selectedMember = member;

      // تنبيه: اختيار فرد من الشريط العلوي هو فلترة بصرية فقط ولا يغير حساب المستخدم المسجل دخوله
      // منفذ العملية يظل دائماً صاحب الحساب المسجل به الدخول حالياً (state.currentUser)

      // تحديث تمييز الأفاتار المختار في الشريط العلوي الثابت بحلقة ذهبية متوهجة وتأثير بارز
      const cards = document.querySelectorAll('.avatar-card');
      cards.forEach(c => {
        if (c.getAttribute('data-member') === member) c.classList.add('active');
        else c.classList.remove('active');
      });

      if (typeof updateUserAndDefaultDisplay === 'function') {
        updateUserAndDefaultDisplay();
      }

      // إعادة رسم وتحديث كافة صفحات البرنامج فوراً
      renderUI();

      let memberDisplayName = member;
      if (member === 'الكل') memberDisplayName = 'كافة المصروفات (إجمالي عام)';
      else if (member === 'البيت') memberDisplayName = 'مصروفات وتكاليف البيت';
      
      const memSel = document.getElementById('opsFilterMember');
      if (memSel) {
        setOperationFilterValues(memSel.id, [member === 'أية' ? 'آية' : member]);
      }
      if (typeof filterOperationsList === 'function') {
        filterOperationsList();
      }
showToast(`👤 تم تصفية العرض على: ${memberDisplayName}`);
    }

    // =========================================================================
    // ربط الحركات بالمشاريع وتجهيز قوائم المشاريع
    // =========================================================================
    function getTransactionProjectName(tx) {
      return String(tx && (tx.project || tx.projectName) || '').trim();
    }

    function getKnownProjects() {
      const namesByKey = new Map();
      const addProjectName = value => {
        const name = String(value || '').trim();
        if (!name) return;
        const key = name.toLocaleLowerCase();
        if (!namesByKey.has(key)) namesByKey.set(key, name);
      };
      (state.monthlyBudgets || []).forEach(b => addProjectName(b?.project));
      (state.transactions || []).forEach(tx => {
        addProjectName(getTransactionProjectName(tx));
      });
      try {
        const savedTasks = JSON.parse(localStorage.getItem('family_monefy_tasks') || '[]');
        if (Array.isArray(savedTasks)) savedTasks.forEach(task => addProjectName(task && task.project));
      } catch (e) {}
      return Array.from(namesByKey.values()).sort((a, b) => a.localeCompare(b, 'ar'));
    }

    function replaceProjectOptions(select, projects, options = {}) {
      if (!select) return;
      const previous = select.value;
      const valueToKeep = previous === '__new_project__' ? (select.dataset.lastValue || '') : previous;
      select.innerHTML = '';

      const firstValue = options.filter ? 'all' : '';
      const firstLabel = options.filter ? (options.allLabel || '📌 كل المشاريع') : 'بدون مشروع';
      select.add(new Option(firstLabel, firstValue));
      projects.forEach(name => select.add(new Option(name, name)));

      if (options.filter) select.add(new Option('بدون مشروع', '__no_project__'));
      if (valueToKeep && valueToKeep !== '__no_project__' && !projects.includes(valueToKeep)) {
        select.add(new Option(valueToKeep, valueToKeep));
      }
      if (options.create) select.add(new Option('＋ إنشاء مشروع جديد', '__new_project__'));

      const defaultValue = options.filter ? (state.projectFilter || 'all') : '';
      const desiredValue = options.filter ? (state.projectFilter || valueToKeep || defaultValue) : valueToKeep;
      const hasDesired = Array.from(select.options).some(option => option.value === desiredValue);
      select.value = hasDesired ? desiredValue : defaultValue;
      if (select.value !== '__new_project__') select.dataset.lastValue = select.value;
    }

    function refreshProjectSelectors() {
      const projects = getKnownProjects();
      replaceProjectOptions(document.getElementById('inpTxProject'), projects, { create: true });
      replaceProjectOptions(document.getElementById('editTxProject'), projects, { create: true });
      replaceProjectOptions(document.getElementById('quickTaskProjectSelect'), projects, { create: true });
      refreshOperationProjectFilter(projects);
      replaceProjectOptions(document.getElementById('analyticsProjectFilter'), projects, { filter: true, allLabel: 'كل المشاريع للمقارنة' });
      replaceProjectOptions(document.getElementById('secFilterProject'), projects, { filter: true, allLabel: 'كافة المشاريع 📁' });
    }

    function populateProjectItemOptions(projectName, targetSelectId, selectedValue = '') {
      const select = document.getElementById(targetSelectId);
      if (!select) return;
      select.innerHTML = '<option value="">بدون بند محدد (عام)</option>';

      if (typeof state !== 'undefined' && Array.isArray(state.monthlyBudgets)) {
        const plan = state.monthlyBudgets.find(b => (b.project === projectName || b.title === projectName || b.name === projectName));
        if (plan && Array.isArray(plan.items)) {
          plan.items.forEach(it => {
            const name = it.category || it.name || it.title;
            if (name) {
              const opt = document.createElement('option');
              opt.value = name;
              opt.textContent = `${name} (${it.amount || 0} ج.م)`;
              if (selectedValue === name) opt.selected = true;
              select.appendChild(opt);
            }
          });
        }
      }
      const newOpt = document.createElement('option');
      newOpt.value = '__new_project_item__';
      newOpt.textContent = '＋ إضافة بند جديد لهذا المشروع';
      select.appendChild(newOpt);
    }
    window.populateProjectItemOptions = populateProjectItemOptions;

    function handleTxProjectItemSelection(select) {
      if (!select) return;
      if (select.value === '__new_project_item__') {
        const entered = window.prompt('اكتب اسم بند المشروع الجديد (مثال: سباكة، دهانات، مصنعيات):');
        const itemName = String(entered || '').trim();
        if (!itemName) {
          select.value = select.dataset.lastValue || '';
          return;
        }
        // Save new item into project plan in state.monthlyBudgets
        const isEdit = (select.id === 'editTxProjectItem');
        const projSelect = document.getElementById(isEdit ? 'editTxProject' : 'inpTxProject');
        const projName = projSelect ? projSelect.value : '';

        if (projName && typeof state !== 'undefined' && Array.isArray(state.monthlyBudgets)) {
          let plan = state.monthlyBudgets.find(b => (b.project === projName || b.title === projName));
          if (!plan) {
            plan = { id: `proj_${Date.now()}`, project: projName, title: projName, type: 'project', items: [] };
            state.monthlyBudgets.push(plan);
          }
          plan.items = plan.items || [];
          if (!plan.items.some(it => it.category === itemName)) {
            plan.items.push({ id: `item_${Date.now()}`, category: itemName, amount: 0 });
            localStorage.setItem('family_monefy_monthly_budgets', JSON.stringify(state.monthlyBudgets));
          }
        }

        const opt = new Option(itemName, itemName, true, true);
        const lastOpt = select.querySelector('option[value="__new_project_item__"]');
        select.insertBefore(opt, lastOpt || null);
        select.value = itemName;
      }
      select.dataset.lastValue = select.value;
    }
    window.handleTxProjectItemSelection = handleTxProjectItemSelection;

    function handleTxProjectSelection(select) {
      if (!select) return;
      if (select.value === '__new_project__') {
        const entered = window.prompt('اكتب اسم المشروع الجديد:');
        const name = String(entered || '').trim();
        if (!name) {
          select.value = select.dataset.lastValue || '';
          return;
        }
        const existing = getKnownProjects().find(project => project.toLocaleLowerCase() === name.toLocaleLowerCase());
        const selectedName = existing || name;
        if (!Array.from(select.options).some(option => option.value === selectedName)) {
          const option = new Option(selectedName, selectedName);
          const createOption = Array.from(select.options).find(item => item.value === '__new_project__');
          select.insertBefore(option, createOption || null);
        }
        select.value = selectedName;
      }
      select.dataset.lastValue = select.value;

      // Dual-Layer WBS logic: Show/hide projectItem field
      const isEdit = (select.id === 'editTxProject');
      const itemGroup = document.getElementById(isEdit ? 'groupEditTxProjectItem' : 'groupTxProjectItem');
      const itemSelectId = isEdit ? 'editTxProjectItem' : 'inpTxProjectItem';

      if (select.value && select.value !== '__new_project__') {
        if (itemGroup) itemGroup.style.display = 'block';
        populateProjectItemOptions(select.value, itemSelectId);
      } else {
        if (itemGroup) itemGroup.style.display = 'none';
        const itemSelect = document.getElementById(itemSelectId);
        if (itemSelect) itemSelect.value = '';
      }
    }

    function setProjectFilter(project) {
      state.projectFilter = project || 'all';
      refreshProjectSelectors();
      refreshOperationProjectFilter(getKnownProjects(), [state.projectFilter]);
      renderUI();
    }

    // =========================================================================
    // نافذة تسجيل حركة جديدة (Tx Modal with Inline Calc, Default Family & Receipt)
    // =========================================================================
    function openTxModal(type = 'expense', preCat = null) {
      currentModalType = type;
      if (typeof initMemberPhotoPickers === 'function') {
        initMemberPhotoPickers();
      }
      const titleEl = document.getElementById('txModalTitleText');
      const iconEl = document.getElementById('txModalTitleIcon');
      const bannerEl = document.getElementById('txNatureBanner');
      const bannerTxt = document.getElementById('txNatureText');
      const btnSaveTxt = document.getElementById('btnSaveTxText');
      const memberSel = document.getElementById('inpTxMember');
      const catSel = document.getElementById('inpTxCategory');
      const amountInp = document.getElementById('inpTxAmount');
      const labelInp = document.getElementById('inpTxLabel');
      const dateInp = document.getElementById('inpTxDate');

      refreshProjectSelectors();

      if (amountInp) amountInp.value = '';
      if (labelInp) labelInp.value = '';
      if (dateInp) dateInp.value = getLocalDateStr(new Date());
      const txProjectSelect = document.getElementById('inpTxProject');
      if (txProjectSelect) {
        txProjectSelect.value = state.projectFilter && state.projectFilter !== 'all' && state.projectFilter !== '__no_project__' ? state.projectFilter : '';
        txProjectSelect.dataset.lastValue = txProjectSelect.value;
      }
      clearReceiptUpload();

      if (catSel) {
        catSel.innerHTML = '';
        const list = (type === 'income') ? INCOME_CATEGORIES : EXPENSE_CATEGORIES;
        list.forEach(c => {
          const opt = document.createElement('option');
          opt.value = c.id;
          opt.textContent = `${c.name}`;
          catSel.appendChild(opt);
        });
        if (preCat) catSel.value = preCat;
      }

      // الديفولت الأوتوماتيكي:
      // عند فتح تسجيل مصروف جديد في حالة عدم اختيار شخص يكون الافتراضي هو "البيت"
      if (memberSel) {
        let defMember = 'البيت';
        if (type === 'expense') {
          if (state.currentMemberFilter && state.currentMemberFilter !== 'الكل') {
            defMember = state.currentMemberFilter;
          } else {
            defMember = 'البيت';
          }
        } else {
          defMember = (state.currentMemberFilter && state.currentMemberFilter !== 'الكل') ? state.currentMemberFilter : 'ماهر';
        }
        memberSel.value = defMember;
        if (typeof selectTxMemberPicker === 'function') {
          selectTxMemberPicker(defMember);
        }
      }

      const execBadge = document.getElementById('txModalExecutorBadge');
      if (execBadge) execBadge.textContent = state.currentUser || 'ماهر';

      if (type === 'income') {
        if (titleEl) titleEl.textContent = 'تسجيل دخل جديد';
        if (iconEl) { iconEl.className = 'fa-solid fa-circle-plus'; iconEl.style.color = '#10b981'; }
        if (bannerEl) bannerEl.className = 'tx-nature-banner income-nature';
        if (bannerTxt) bannerTxt.textContent = 'وارد / إيداع جديد إلى الرصيد';
        if (btnSaveTxt) btnSaveTxt.textContent = 'حفظ الدخل فوراً';
      } else {
        if (titleEl) titleEl.textContent = 'تسجيل مصروف جديد';
        if (iconEl) { iconEl.className = 'fa-solid fa-circle-minus'; iconEl.style.color = '#ef4444'; }
        if (bannerEl) bannerEl.className = 'tx-nature-banner expense-nature';
        if (bannerTxt) bannerTxt.textContent = 'مصروف / خصم جديد من الرصيد';
        if (btnSaveTxt) btnSaveTxt.textContent = 'حفظ المصروف فوراً';
      }

      openModal('txModal');
    }

    function handleSaveTx() {
      const amountInp = document.getElementById('inpTxAmount');
      const labelInp = document.getElementById('inpTxLabel');
      const catInp = document.getElementById('inpTxCategory');
      const memberInp = document.getElementById('inpTxMember');
      const walletInp = document.getElementById('inpTxWallet');
      const dateInp = document.getElementById('inpTxDate');
      const errHint = document.getElementById('txLabelError');

      const amount = parseFloat(amountInp ? amountInp.value : 0);
      const label = labelInp ? labelInp.value.trim() : '';

      if (isNaN(amount) || amount <= 0) {
        showToast('⚠️ الرجاء إدخال مبلغ صحيح أكبر من الصفر');
        if (amountInp) amountInp.focus();
        return;
      }

      if (!label) {
        if (errHint) errHint.style.display = 'block';
        if (labelInp) {
          labelInp.focus();
          labelInp.classList.add('error');
        }
        showToast('⚠️ بيان الحركة إلزامي لتسجيل المصروف أو الدخل!');
        return;
      }
      if (errHint) errHint.style.display = 'none';

      const localToday = typeof getLocalDateStr === 'function' ? getLocalDateStr(new Date()) : new Date().toISOString().split('T')[0];
      const newTx = {
        id: 'tx-' + Date.now(),
        type: currentModalType,
        amount: amount,
        label: label,
        category: catInp ? catInp.value : 'other',
        member: (memberInp && memberInp.value) ? memberInp.value : (state.selectedMember !== 'الكل' ? state.selectedMember : 'البيت'),
        walletId: walletInp && walletInp.value ? walletInp.value : (state.currentWalletId !== 'all' ? state.currentWalletId : 'wallet-cash-safe'),
        date: dateInp && dateInp.value ? dateInp.value : localToday,
        project: (document.getElementById('inpTxProject')?.value || '').trim() || null,
        projectItem: (document.getElementById('inpTxProjectItem')?.value || '').trim() || null,
        time: new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' }),
        author: state.currentUser || 'ماهر',
        receipt: state.pendingReceiptDataUri || (state.pendingReceiptDataUris && state.pendingReceiptDataUris[0]) || null,
        receipts: (state.pendingReceiptDataUris && state.pendingReceiptDataUris.length) ? [...state.pendingReceiptDataUris] : (state.pendingReceiptDataUri ? [state.pendingReceiptDataUri] : [])
      };

      if (currentModalType === 'expense') {
        if (typeof canDeductFromWallet === 'function' && !canDeductFromWallet(newTx.walletId, newTx.amount)) {
          if (typeof showToast === 'function') {
            showToast('⚠️ تنبيه: تم تسجيل المصروف مع سحب على المكشوف للمحفظة', 'warning', 3500);
          }
        }
      }
      newTx.serialNo = generateNextAuditSerial(newTx.type, newTx.date);
      state.transactions.unshift(newTx);
      saveTx();
      if (newTx.type === 'expense') checkCategoryBudgetCeilingTrigger(newTx.category, newTx.amount);
      // ضمان ظهور الحركة الجديدة فوراً في صفحة العمليات المسجلة بإزالة أي حجب مؤقت
      try {
        const opsSearch = document.getElementById('opsSearchInput');
        if (opsSearch) opsSearch.value = '';
        state.searchQuery = '';
        opsTypeFilterState = 'all';
        const typeChips = document.querySelectorAll('.ops-type-chip');
        typeChips.forEach(c => {
          if (c.getAttribute('data-type') === 'all') c.classList.add('active');
          else c.classList.remove('active');
        });
        ['opsFilterCategory', 'opsFilterMember', 'opsFilterProject'].forEach(id => setOperationFilterValues(id, []));
        state.projectFilter = 'all';
        refreshProjectSelectors();
      } catch(e) {}

      logActivity({
        type: currentModalType === 'income' ? 'add_income' : 'add_expense',
        action: currentModalType === 'income' ? 'إضافة دخل' : 'تسجيل مصروف',
        label: `${label} (${getCategoryName(newTx.category)})`,
        amount: amount,
        sign: currentModalType === 'income' ? '+' : '-',
        member: newTx.member,
        author: state.currentUser || 'ماهر',
        wallet: (typeof getWalletName === 'function' ? getWalletName(newTx.walletId) : newTx.walletId),
        category: (typeof getCategoryName === 'function' ? getCategoryName(newTx.category) : newTx.category),
        receipt: newTx.receipt,
        notes: `مسجل في محفظة: ${(typeof getWalletName === 'function' ? getWalletName(newTx.walletId) : newTx.walletId)}`
      });

      playNotificationChime();
      closeModal('txModal');
      renderUI();
      
      filterOperationsList();
      const opTypeName = currentModalType === 'income' ? 'إثبات دخل' : 'مصروف';
      const catOrLabel = (newTx.label && newTx.label !== 'مصروف' && newTx.label !== 'دخل') ? newTx.label : (typeof getCategoryName === 'function' ? getCategoryName(newTx.category) : newTx.category);
      const currSym = (state.currency === 'SAR') ? 'ر.س' : (state.currency === 'GOLD21' ? 'جرام' : 'ج.م');
      showToast(`✅ تم تسجيل عملية ${opTypeName} (${catOrLabel}) بقيمة ${formatMoney(amount)} ${currSym} بنجاح`, 'success', 4500);
    }

    function deleteTx(id) {
      const tx = (state.transactions || []).find(t => t.id === id);
      if (!tx) return;

      const opTypeName = tx.type === 'income' ? 'دخل' : 'صرف';
      const delUser = state.currentUser || 'ماهر';

      // 1. طلب سبب الحذف إلزامياً للتدقيق والرقابة المالية
      const reason = prompt(`ما سبب حذف حركة: "${tx.label}" بقيمة (${Number(tx.amount).toLocaleString('ar-EG')} ج.م)؟\n(إلزامي لتوثيق الأثر المالي والرقابي):`);
      if (reason === null) {
        // ألغى المستخدم العملية
        return;
      }
      const trimmedReason = reason.trim();
      if (!trimmedReason) {
        if (typeof showToast === 'function') showToast('⚠️ يجب كتابة سبب الحذف لتوثيق الأثر المالي والرقابي', 'error', 4500);
        return;
      }

      // 2. أرشفة العملية قبل الحذف في أرشيف العمليات المحذوفة بكامل بياناتها والأثر الرقابي
      const deletedRecord = {
        ...tx,
        isDeleted: true,
        deletedAt: new Date().toISOString(),
        deletedBy: delUser,
        deleteReason: trimmedReason,
        auditTrail: [
          ...(tx.auditTrail || []),
          {
            action: 'delete',
            timestamp: new Date().toISOString(),
            user: delUser,
            reason: trimmedReason,
            before: { ...tx },
            after: null
          }
        ]
      };

      state.deletedTransactions = state.deletedTransactions || [];
      state.deletedTransactions.unshift(deletedRecord);
      try {
        localStorage.setItem('family_deleted_tx_archive', JSON.stringify(state.deletedTransactions.slice(0, 500)));
      } catch(e) {}

      // 3. حذف الحركة من العمليات النشطة وحفظ الحالة
      state.transactions = state.transactions.filter(t => t.id !== id);
      saveTx();

      // 4. إطلاق تنبيه وتوثيق النشاط
      const alertMsg = `قام المستخدم ${delUser} بحذف عملية ${opTypeName} "${tx.label}" بقيمة (${Number(tx.amount).toLocaleString('ar-EG')} ج.م) - السبب: ${trimmedReason}`;
      if (typeof addFamilyAlert === 'function') {
        addFamilyAlert('audit_deletion', alertMsg, 'delete');
      }

      logActivity({
        type: 'delete_tx',
        action: 'حذف حركة',
        label: `حذف: ${tx.label} (السبب: ${trimmedReason})`,
        amount: tx.amount,
        member: tx.member,
        author: delUser
      });

      renderUI();
      if (typeof filterOperationsList === 'function') filterOperationsList();
      showToast(`🗑️ تم أرشفة وحذف الحركة وتوثيق السبب: ${trimmedReason}`, 'info', 4500);
    }

        // دالة توحيد وترقية معرفات المحافظ للعمليات التاريخية
    function normalizeWalletId(wId) {
      if (!wId) return 'wallet-cash-safe';
      if (wId === 'cash') return 'wallet-cash-safe';
      if (wId === 'wallet-cash-safe' || wId === 'wallet-default' || wId === 'wallet-home-cash') return 'wallet-cash-safe';
      if (wId === 'wallet-vodafone') return 'wallet-vodafone';
      if (wId === 'wallet-reserve' || wId === 'wallet-bank-misr') return 'wallet-reserve';
      if (wId === 'wallet-other' || wId === 'wallet-instapay' || wId === 'wallet-cib-credit') return 'wallet-other';
      if (wId === 'wallet-ahly') return 'wallet-cash-safe';
      return wId;
    }

    
    // ==============================================================
    // [v5.3.89] الفحص المحاسبي الصارم لمنع الصرف أو التحويل بأكثر من الرصيد الفعلي
    // ==============================================================
    function getWalletActualBalance(walletIdOrName) {
      if (typeof auditAndRecomputeAllWalletBalances === 'function') {
        auditAndRecomputeAllWalletBalances();
      }
      if (!walletIdOrName || !Array.isArray(state.wallets)) return 0;
      const val = String(walletIdOrName);
      const normalized = typeof normalizeWalletId === 'function' ? normalizeWalletId(val) : val;
      const w = state.wallets.find(wallet => wallet && (wallet.id === val || wallet.name === val || wallet.id === normalized));
      return w ? (Number(w.balance) || 0) : 0;
    }
    window.getWalletActualBalance = getWalletActualBalance;

    function canDeductFromWallet(walletId, amount, excludeTxId = null) {
      if (typeof auditAndRecomputeAllWalletBalances === 'function') {
        auditAndRecomputeAllWalletBalances();
      }
      const amt = Math.abs(Number(amount) || 0);
      if (amt <= 0) return true;
      if (!walletId || !Array.isArray(state.wallets)) return false;

      const val = String(walletId);
      const normalized = typeof normalizeWalletId === 'function' ? normalizeWalletId(val) : val;
      const w = state.wallets.find(item => item && (item.id === val || item.name === val || item.id === normalized));
      if (!w) return false;

      let currentBal = Number(w.balance) || 0;

      // عند تعديل حركة موجودة مسبقاً، يتم استرجاع أثرها السابق مؤقتاً للتحقق
      if (excludeTxId && Array.isArray(state.transactions)) {
        const prevTx = state.transactions.find(t => t && t.id === excludeTxId);
        if (prevTx) {
          const prevAmt = Math.abs(Number(prevTx.amount) || 0);
          if (prevTx.type === 'expense' && (prevTx.walletId === w.id || prevTx.wallet === w.id || prevTx.walletId === w.name)) {
            currentBal += prevAmt;
          } else if (prevTx.type === 'transfer' && (prevTx.fromWalletId === w.id || prevTx.fromWallet === w.id)) {
            currentBal += prevAmt;
          }
        }
      }

      return (currentBal + 0.0001) >= amt;
    }
    window.canDeductFromWallet = canDeductFromWallet;

function auditAndRecomputeAllWalletBalances() {
      if (!Array.isArray(state.wallets)) state.wallets = [];
      const transactions = Array.isArray(state.transactions) ? state.transactions.filter(tx => tx && !tx.deleted) : [];
      const findWallet = reference => {
        if (reference === undefined || reference === null || reference === '') return null;
        const value = String(reference);
        if (value === 'all') return state.wallets.find(wallet => wallet && wallet.isDefault) || state.wallets[0] || null;
        const normalized = normalizeWalletId(value);
        return state.wallets.find(wallet => wallet.id === value || wallet.name === value || wallet.id === normalized) || null;
      };
      const effectForWallet = (wallet, tx) => {
        const amount = Math.abs(Number(tx.amount) || 0);
        if (!amount) return 0;
        if (tx.type === 'transfer') {
          const fromWallet = findWallet(tx.fromWalletId || tx.fromWallet || tx.walletId || tx.wallet);
          const toWallet = findWallet(tx.toWalletId || tx.toWallet);
          return (fromWallet && fromWallet.id === wallet.id ? -amount : 0) +
            (toWallet && toWallet.id === wallet.id ? amount : 0);
        }
        const txWallet = findWallet(tx.walletId || tx.wallet || 'wallet-cash-safe');
        if (!txWallet || txWallet.id !== wallet.id) return 0;
        if (tx.type === 'income') return amount;
        if (tx.type === 'expense') return -amount;
        return 0;
      };

      state.wallets.forEach(wallet => {
        if (!wallet || typeof wallet !== 'object') return;
        const netTransactions = transactions.reduce((sum, tx) => sum + effectForWallet(wallet, tx), 0);
        const explicitOpening = Number(wallet.initialBalance ?? wallet.baseBalance);
        let openingBalance;
        if (Number.isFinite(explicitOpening)) {
          const openingWasAlreadyRecorded = transactions.some(tx =>
            tx.type === 'income' &&
            String(tx.label || '').startsWith('رصيد افتتاحي لمحفظة') &&
            findWallet(tx.walletId || tx.wallet) === wallet &&
            Math.abs(Math.abs(Number(tx.amount) || 0) - explicitOpening) < 0.01
          );
          openingBalance = openingWasAlreadyRecorded ? 0 : explicitOpening;
          if (openingWasAlreadyRecorded) wallet.initialBalance = 0;
        } else {
          const savedBalance = Number(wallet.balance);
          openingBalance = Number.isFinite(savedBalance) ? savedBalance - netTransactions : 0;
          wallet.initialBalance = openingBalance;
        }
        const balance = Math.round((openingBalance + netTransactions + Number.EPSILON) * 100) / 100;
        wallet.balance = Object.is(balance, -0) ? 0 : balance;
      });

      try { localStorage.setItem('family_monefy_wallets', JSON.stringify(state.wallets)); } catch(e) {
        console.warn('تعذر حفظ أرصدة المحافظ بعد المراجعة.');
      }
      return state.wallets;
    }
    window.auditAndRecomputeAllWalletBalances = auditAndRecomputeAllWalletBalances;

    
    // =========================================================================
    // نظام الترقيم والسريال الذكي للعمليات المالية (Smart Audit Serial Engine)
    // =========================================================================
    function ensureSmartAuditSerials() {
      if (!state.transactions || !Array.isArray(state.transactions)) return;
      // ترتيب الحركات تصاعدياً تاريخياً لضمان ثبات السريال الزمني
      const sorted = [...state.transactions].sort((a, b) => {
        const da = (a.date || '') + ' ' + (a.time || '');
        const db = (b.date || '') + ' ' + (b.time || '');
        return da.localeCompare(db);
      });
      
      let maxSeq = 0;
      sorted.forEach(t => {
        if (t.serialNo) {
          const parts = t.serialNo.split('-');
          const num = parseInt(parts[parts.length - 1], 10);
          if (!isNaN(num) && num > maxSeq) maxSeq = num;
        }
      });

      let assignedCount = 0;
      sorted.forEach(t => {
        if (!t.serialNo) {
          maxSeq++;
          const yr = t.date ? t.date.substring(0, 4) : '2026';
          const prefix = t.type === 'income' ? 'INC' : 'EXP';
          t.serialNo = `${prefix}-${yr}-${String(maxSeq).padStart(4, '0')}`;
          assignedCount++;
        }
      });
      if (assignedCount > 0) {
        try {
          localStorage.setItem('family_monefy_transactions', JSON.stringify(state.transactions));
        } catch(e) {}
      }
    }

    function generateNextAuditSerial(type, dateStr) {
      ensureSmartAuditSerials();
      if (typeof ensureSmartRequestSerials === 'function') ensureSmartRequestSerials();
      let maxSeq = 0;
      (state.transactions || []).forEach(t => {
        if (t.serialNo) {
          const parts = t.serialNo.split('-');
          const num = parseInt(parts[parts.length - 1], 10);
          if (!isNaN(num) && num > maxSeq) maxSeq = num;
        }
      });
      const yr = dateStr ? dateStr.substring(0, 4) : '2026';
      const prefix = type === 'income' ? 'INC' : 'EXP';
      return `${prefix}-${yr}-${String(maxSeq + 1).padStart(4, '0')}`;
    }

function saveTx() {
      familyAlerts.observe(state.transactions, state.currentUser);
      if (typeof auditAndRecomputeAllWalletBalances === 'function') auditAndRecomputeAllWalletBalances();

      // 1. التخزين الفوري في قاعدة بيانات IndexedDB عالية السعة وبدون سقف 5MB
      if (window.FamilyDB) {
        window.FamilyDB.putMany('transactions', state.transactions);
        window.FamilyDB.putMany('wallets', state.wallets);
      }

      try {
        localStorage.setItem('family_monefy_v2_tx', JSON.stringify(state.transactions));
      } catch(e) {
        console.warn('LocalStorage limit reached; data safely secured in IndexedDB:', e);
      }

      // 2. جدولة المزامنة التلقائية مع Google Drive
      if (window.FamilyDriveSync) {
        window.FamilyDriveSync.queueSync();
      }

      if (typeof triggerDriveAutoSync === 'function') triggerDriveAutoSync();
      try {
        syncChannel.postMessage({
          type: 'SYNC_TX',
          transactions: state.transactions,
          wallets: state.wallets,
          author: state.currentUser
        });
      } catch(e) {}
    }

    // =========================================================================
    // إدارة رفع وتصوير الفواتير (Receipt Camera / Upload)
    // =========================================================================
    function handleReceiptUpload(event) {
      const files = event.target.files ? Array.from(event.target.files) : [];
      if (!files.length) return;
      if (!state.pendingReceiptDataUris) state.pendingReceiptDataUris = [];

      let loaded = 0;
      files.forEach(file => {
        const reader = new FileReader();
        reader.onload = function(e) {
          const img = new Image();
          img.onload = function() {
            const canvas = document.createElement('canvas');
            const maxDim = 800;
            let w = img.width, h = img.height;
            if (w > h && w > maxDim) { h = Math.round((h * maxDim) / w); w = maxDim; }
            else if (h > maxDim) { w = Math.round((w * maxDim) / h); h = maxDim; }
            canvas.width = w; canvas.height = h;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, w, h);
            const compressedDataUri = canvas.toDataURL('image/jpeg', 0.82);
            state.pendingReceiptDataUris.push(compressedDataUri);
            state.pendingReceiptDataUri = state.pendingReceiptDataUris[0] || null;
            loaded++;
            if (loaded === files.length) {
              renderReceiptPreviewsCarousel();
              showToast(`📷 تم إرفاق ${files.length} مرفقات بنجاح`);
            }
          };
          img.src = e.target.result;
        };
        reader.readAsDataURL(file);
      });
      event.target.value = '';
    }

    function renderReceiptPreviewsCarousel() {
      const previewCont = document.getElementById('receiptPreviewContainer');
      const clearBtn = document.getElementById('btnClearReceipt');
      const badge = document.getElementById('txPhotoAttachedBadge');
      const uris = state.pendingReceiptDataUris || [];

      if (!uris.length) {
        if (previewCont) previewCont.style.display = 'none';
        if (clearBtn) clearBtn.style.display = 'none';
        if (badge) badge.style.display = 'none';
        return;
      }

      if (previewCont) {
        previewCont.style.display = 'block';
        previewCont.innerHTML = `
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
            <span style="font-size: 0.72rem; color: #38bdf8; font-weight: 850;">المرفقات (${uris.length}) - مرر أفقياً للمعاينة:</span>
            <button type="button" onclick="clearReceiptUpload()" style="background: rgba(239, 68, 68, 0.2); border: 1px solid rgba(239, 68, 68, 0.4); color: #f87171; border-radius: 6px; padding: 2px 8px; font-size: 0.68rem; cursor: pointer;">حذف الكل</button>
          </div>
          <div style="display: flex; gap: 8px; overflow-x: auto; padding: 4px 2px; scrollbar-width: thin;">
            ${uris.map((uri, i) => `
              <div style="position: relative; width: 64px; height: 64px; border-radius: 8px; overflow: hidden; border: 1.5px solid #38bdf8; flex-shrink: 0; background: #0f172a;">
                <img src="${uri}" onclick="openReceiptLightbox('${uri}', 'مرفق ${i+1}')" style="width: 100%; height: 100%; object-fit: cover; cursor: pointer;">
                <button type="button" onclick="removeSingleReceipt(${i})" style="position: absolute; top: 2px; right: 2px; width: 18px; height: 18px; border-radius: 50%; background: rgba(239, 68, 68, 0.9); color: #fff; border: none; font-size: 0.65rem; cursor: pointer; display: flex; align-items: center; justify-content: center;">&times;</button>
              </div>
            `).join('')}
          </div>
        `;
      }
      if (clearBtn) clearBtn.style.display = 'none'; // Replaced by inline delete all
      if (badge) badge.style.display = 'inline-flex';
    }

    function removeSingleReceipt(idx) {
      if (!state.pendingReceiptDataUris) return;
      state.pendingReceiptDataUris.splice(idx, 1);
      state.pendingReceiptDataUri = state.pendingReceiptDataUris[0] || null;
      renderReceiptPreviewsCarousel();
    }

    function clearReceiptUpload() {
      state.pendingReceiptDataUri = null;
      state.pendingReceiptDataUris = [];
      const inp = document.getElementById('inpTxReceipt');
      if (inp) inp.value = '';
      const previewCont = document.getElementById('receiptPreviewContainer');
      const clearBtn = document.getElementById('btnClearReceipt');
      if (previewCont) {
        previewCont.style.display = 'none';
        previewCont.innerHTML = '<img id="receiptPreviewCarouselSingle" src="" alt="معاينة الإيصال" style="max-height: 120px; border-radius: 8px; object-fit: cover;">';
      }
      if (clearBtn) clearBtn.style.display = 'none';
      const badge = document.getElementById('txPhotoAttachedBadge'); if (badge) badge.style.display = 'none';
    }

    // =========================================================================
    // محرك معرض الصور والمرفقات المتعددة والتنقل السلس (Multi-Image Gallery Engine) v5.3.89
    // =========================================================================
    window.galleryLightboxState = {
      images: [],
      currentIndex: 0,
      title: ''
    };

    function renderGalleryLightbox() {
      const st = window.galleryLightboxState;
      const img = document.getElementById('lightboxImg');
      const counter = document.getElementById('lightboxCounterPill');
      const lbl = document.getElementById('lightboxTxLabel');
      const prevBtn = document.getElementById('lightboxPrevBtn');
      const nextBtn = document.getElementById('lightboxNextBtn');
      const strip = document.getElementById('lightboxThumbnailsStrip');

      if (!img) return;
      if (!st || !st.images || !st.images.length) {
        img.src = '';
        if (counter) counter.textContent = '0 / 0';
        if (strip) strip.innerHTML = '';
        return;
      }

      const total = st.images.length;
      if (st.currentIndex < 0) st.currentIndex = 0;
      if (st.currentIndex >= total) st.currentIndex = total - 1;

      img.style.opacity = '0.35';
      setTimeout(() => {
        img.src = st.images[st.currentIndex];
        img.style.opacity = '1';
      }, 50);

      if (counter) counter.textContent = `${st.currentIndex + 1} / ${total}`;
      if (lbl) lbl.textContent = st.title || '';

      if (prevBtn) {
        prevBtn.style.display = total > 1 ? 'flex' : 'none';
        prevBtn.style.opacity = st.currentIndex === 0 ? '0.3' : '1';
        prevBtn.disabled = (st.currentIndex === 0);
      }
      if (nextBtn) {
        nextBtn.style.display = total > 1 ? 'flex' : 'none';
        nextBtn.style.opacity = st.currentIndex === total - 1 ? '0.3' : '1';
        nextBtn.disabled = (st.currentIndex === total - 1);
      }

      if (strip) {
        if (total <= 1) {
          strip.innerHTML = '';
          strip.style.display = 'none';
        } else {
          strip.style.display = 'flex';
          strip.innerHTML = st.images.map((src, i) => `
            <div onclick="setLightboxIndex(${i})" style="flex-shrink: 0; width: 48px; height: 48px; border-radius: 8px; overflow: hidden; cursor: pointer; border: 2px solid ${i === st.currentIndex ? '#38bdf8' : 'rgba(255,255,255,0.2)'}; transform: ${i === st.currentIndex ? 'scale(1.1)' : 'scale(1)'}; box-shadow: ${i === st.currentIndex ? '0 0 10px rgba(56,189,248,0.6)' : 'none'}; transition: all 0.2s ease;">
              <img src="${src}" style="width: 100%; height: 100%; object-fit: cover;">
            </div>
          `).join('');
        }
      }
    }

    function navLightboxGallery(dir) {
      const st = window.galleryLightboxState;
      if (!st || !st.images || !st.images.length) return;
      const nextIdx = st.currentIndex + dir;
      if (nextIdx >= 0 && nextIdx < st.images.length) {
        st.currentIndex = nextIdx;
        renderGalleryLightbox();
      }
    }
    window.navLightboxGallery = navLightboxGallery;

    function setLightboxIndex(idx) {
      const st = window.galleryLightboxState;
      if (!st || !st.images || !st.images.length) return;
      if (idx >= 0 && idx < st.images.length) {
        st.currentIndex = idx;
        renderGalleryLightbox();
      }
    }
    window.setLightboxIndex = setLightboxIndex;

    function downloadActiveLightboxPhoto() {
      const st = window.galleryLightboxState;
      if (!st || !st.images || !st.images.length) return;
      const src = st.images[st.currentIndex];
      if (!src) return;
      const a = document.createElement('a');
      a.href = src;
      a.download = `attachment-${st.currentIndex + 1}-${Date.now()}.jpg`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }
    window.downloadActiveLightboxPhoto = downloadActiveLightboxPhoto;

    function openActiveLightboxPhotoInNewTab() {
      const st = window.galleryLightboxState;
      if (!st || !st.images || !st.images.length) return;
      const src = st.images[st.currentIndex];
      if (src) {
        const w = window.open('');
        w.document.write(`<body style="margin:0; background:#0f172a; display:flex; align-items:center; justify-content:center; min-height:100vh;"><img src="${src}" style="max-width:98%; max-height:98vh; object-fit:contain; border-radius:10px;"></body>`);
      }
    }
    window.openActiveLightboxPhotoInNewTab = openActiveLightboxPhotoInNewTab;

    function openReceiptLightbox(source, optionalTitle = '', initialIndex = 0) {
      const header = document.getElementById('lightboxHeaderTitle');
      if (!source) {
        if (typeof showToast === 'function') showToast('عفواً، لا توجد صورة مرفقة لعرضها');
        return;
      }

      let images = [];
      let title = optionalTitle || '';
      let curIdx = initialIndex || 0;

      // 1. إذا كان المصدر مصفوفة صور
      if (Array.isArray(source)) {
        images = source.filter(Boolean);
      }
      // 2. إذا كان المصدر كائناً (Transaction / Commitment / Debt / Bill)
      else if (typeof source === 'object' && source !== null) {
        if (Array.isArray(source.receipts) && source.receipts.length) {
          images = source.receipts;
        } else if (Array.isArray(source.attachments) && source.attachments.length) {
          images = source.attachments;
        } else if (source.receipt || source.photo || source.receiptDataUri || source.receiptUrl) {
          images = [source.receipt || source.photo || source.receiptDataUri || source.receiptUrl];
        }
        title = title || source.label || source.title || 'مرفق مصور';
      }
      // 3. إذا كان المصدر معرف عملية (ID string)
      else if (typeof source === 'string' && (source.startsWith('tx-') || source.startsWith('exp-') || source.startsWith('debt-') || (source.length < 40 && !source.startsWith('data:') && !source.startsWith('http') && !source.startsWith('blob:')))) {
        const tx = (state.transactions || []).find(t => t.id === source);
        const exp = (state.expectedExpenses || []).find(e => e.id === source);
        const debt = (state.debts || []).find(d => d.id === source);
        const target = tx || exp || debt;

        if (target) {
          if (Array.isArray(target.receipts) && target.receipts.length) {
            images = target.receipts;
          } else if (Array.isArray(target.attachments) && target.attachments.length) {
            images = target.attachments;
          } else if (target.receipt || target.photo || target.receiptDataUri || target.receiptUrl) {
            images = [target.receipt || target.photo || target.receiptDataUri || target.receiptUrl];
          }
          title = title || `${target.label || target.title || 'عملية'} (${(typeof formatMoney === 'function') ? formatMoney(target.amount) : target.amount + ' ج.م'})`;
        }
      }
      // 4. إذا كان المصدر مسار صورة أو Base64 فردي
      if (!images.length && typeof source === 'string') {
        let foundSibling = false;
        const allItems = [...(state.transactions || []), ...(state.expectedExpenses || []), ...(state.debts || [])];
        for (const item of allItems) {
          const recs = (Array.isArray(item.receipts) && item.receipts.length) ? item.receipts : ((Array.isArray(item.attachments) && item.attachments.length) ? item.attachments : null);
          if (recs && recs.includes(source)) {
            images = recs;
            curIdx = recs.indexOf(source);
            title = title || `${item.label || item.title || 'عملية'} (${(typeof formatMoney === 'function') ? formatMoney(item.amount) : item.amount + ' ج.م'})`;
            foundSibling = true;
            break;
          }
        }
        if (!foundSibling) {
          images = [source];
          curIdx = 0;
        }
      }

      if (!images.length) {
        if (typeof showToast === 'function') showToast('عفواً، لا توجد صورة مرفقة لعرضها');
        return;
      }

      if (header) {
        header.textContent = images.length > 1 ? `معاينة المرفقات المصورة (${images.length})` : 'معاينة الصورة المرفقة';
      }

      window.galleryLightboxState = {
        images: images,
        currentIndex: Math.max(0, Math.min(curIdx, images.length - 1)),
        title: title
      };

      renderGalleryLightbox();
      openModal('receiptLightboxModal');
      const lb = document.getElementById('receiptLightboxModal');
      if (lb) lb.style.setProperty('z-index', '1200050', 'important');
    }
    window.openReceiptLightbox = openReceiptLightbox;

    function viewReceiptImage(dataUri) {
      if (!dataUri) return;
      openReceiptLightbox(dataUri, 'إيصال العملية');
    }
    window.viewReceiptImage = viewReceiptImage;

    // إيماءات اللمس والتمرير السريع
    let _lbTouchStartX = 0;
    let _lbTouchEndX = 0;
    function setupLightboxTouchGestures() {
      const stage = document.getElementById('lightboxViewerStage');
      if (!stage || stage._swipeAttached) return;
      stage._swipeAttached = true;
      stage.addEventListener('touchstart', (e) => {
        if (e.changedTouches && e.changedTouches[0]) {
          _lbTouchStartX = e.changedTouches[0].screenX;
        }
      }, { passive: true });
      stage.addEventListener('touchend', (e) => {
        if (e.changedTouches && e.changedTouches[0]) {
          _lbTouchEndX = e.changedTouches[0].screenX;
          const deltaX = _lbTouchEndX - _lbTouchStartX;
          if (Math.abs(deltaX) > 40) {
            if (deltaX < 0) navLightboxGallery(1);
            else navLightboxGallery(-1);
          }
        }
      }, { passive: true });
    }
    document.addEventListener('DOMContentLoaded', setupLightboxTouchGestures);
    setTimeout(setupLightboxTouchGestures, 1000);

    // التنقل بأسهم لوحة المفاتيح
    document.addEventListener('keydown', (e) => {
      const lb = document.getElementById('receiptLightboxModal');
      if (lb && (lb.style.display === 'flex' || lb.classList.contains('open'))) {
        if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
          navLightboxGallery(-1);
        } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
          navLightboxGallery(1);
        } else if (e.key === 'Escape') {
          closeModal('receiptLightboxModal');
        }
      }
    });

    // =========================================================================
    // الآلة الحاسبة المدمجة بجانب خانة المبلغ (Inline Calc Integration)
    // =========================================================================
    
    // =========================================================================
    // محرك الآلة الحاسبة المدمجة والذكية لتسجيل المصاريف والإيرادات
    // =========================================================================
    let txCalcExpr = '0';
    let txCalcCurrentResult = 0;
    let txCalcJustEvaluated = false;

    function toggleTxCalcPad(force) {
      const pad = document.getElementById('txInlineCalcPad');
      if (!pad) return;
      const isOpen = pad.style.display !== 'none';
      const willOpen = force !== undefined ? force : !isOpen;

      if (willOpen) {
        pad.style.display = 'flex';
        const currentAmt = document.getElementById('inpTxAmount')?.value;
        if (currentAmt && !isNaN(parseFloat(currentAmt)) && parseFloat(currentAmt) > 0) {
          txCalcExpr = currentAmt;
          txCalcCurrentResult = parseFloat(currentAmt);
        } else {
          txCalcExpr = '0';
          txCalcCurrentResult = 0;
        }
        txCalcJustEvaluated = false;
        updateTxCalcScreen();
      } else {
        pad.style.display = 'none';
      }
    }

    function updateTxCalcScreen() {
      const formulaEl = document.getElementById('txCalcFormula');
      const resEl = document.getElementById('txCalcResult');
      const badgeEl = document.getElementById('txCalcBadgeVal');

      if (formulaEl) formulaEl.textContent = txCalcExpr;
      const formatted = Number(txCalcCurrentResult || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      if (resEl) resEl.textContent = formatted;
      if (badgeEl) badgeEl.textContent = formatted;
    }

    function evaluateTxExpr(expr) {
      try {
        const sanitized = expr.replace(/×/g, '*').replace(/÷/g, '/').replace(/%/g, '/100');
        if (!/^[0-9+\-*/. ()]+$/.test(sanitized)) return 0;
        const val = Function(`'use strict'; return (${sanitized});`)();
        return isNaN(val) || !isFinite(val) ? 0 : val;
      } catch (e) {
        return 0;
      }
    }

    function txCalcNum(num) {
      if (txCalcJustEvaluated || txCalcExpr === '0') {
        txCalcExpr = (num === '.') ? '0.' : num;
        txCalcJustEvaluated = false;
      } else {
        if (num === '.' && txCalcExpr.endsWith('.')) return;
        txCalcExpr += num;
      }
      txCalcCurrentResult = evaluateTxExpr(txCalcExpr);
      updateTxCalcScreen();
    }

    function txCalcOp(op) {
      txCalcJustEvaluated = false;
      const lastChar = txCalcExpr.slice(-1);
      if (['+', '-', '*', '/', '%'].includes(lastChar)) {
        txCalcExpr = txCalcExpr.slice(0, -1) + op;
      } else {
        txCalcExpr += op;
      }
      updateTxCalcScreen();
    }

    function txCalcClear() {
      txCalcExpr = '0';
      txCalcCurrentResult = 0;
      txCalcJustEvaluated = false;
      updateTxCalcScreen();
    }

    function txCalcBackspace() {
      if (txCalcExpr.length > 1) {
        txCalcExpr = txCalcExpr.slice(0, -1);
      } else {
        txCalcExpr = '0';
      }
      txCalcCurrentResult = evaluateTxExpr(txCalcExpr);
      updateTxCalcScreen();
    }

    function txCalcEquals() {
      txCalcCurrentResult = evaluateTxExpr(txCalcExpr);
      txCalcExpr = Number(txCalcCurrentResult).toFixed(2);
      txCalcJustEvaluated = true;
      updateTxCalcScreen();
    }

    function applyTxCalcResult() {
      txCalcEquals();
      const num = txCalcCurrentResult;
      if (num > 0) {
        const inp = document.getElementById('inpTxAmount');
        if (inp) {
          inp.value = num.toFixed(2);
          inp.focus();
        }
        toggleTxCalcPad(false);
        const labelInp = document.getElementById('inpTxLabel');
        if (labelInp) labelInp.focus();
        showToast(`🔢 تم إدراج المبلغ (${num.toFixed(2)} ج.م) في خانة المبلغ`);
      } else {
        showToast('⚠️ الرجاء حساب أو كتابة مبلغ صحيح أكبر من الصفر أولاً');
      }
    }

    


    // =========================================================================
    // نظام التوزيع والتخصيص المتعدد لطلبات المصروف (Multi-Allocation Builder)
    // =========================================================================
    let currentRequestAllocations = [
      { amount: 0, category: 'daily', member: 'أية' }
    ];

    // مزامنة مؤشر السلايدر التفاعلي للمبلغ المطلوب (100 ج.م لكل خطوة)
    function syncReqAmountFromRange(val) {
      const inp = document.getElementById('inpReqAmount');
      const lbl = document.getElementById('lblReqSliderVal');
      const num = parseFloat(val) || 0;
      if (inp) {
        inp.value = num > 0 ? num : '';
      }
      if (lbl) {
        lbl.textContent = (typeof formatMoney === 'function') ? formatMoney(num) : num + ' ج.م';
      }
      initRequestAllocations();
    }

    // تعديل المبلغ بمقدار 100 جنيه لكل ضغطة على المؤشر أو الأزرار
    function adjustReqAmount(delta) {
      const inp = document.getElementById('inpReqAmount');
      const rng = document.getElementById('rngReqAmount');
      const lbl = document.getElementById('lblReqSliderVal');
      if (!inp) return;
      let cur = parseFloat(inp.value) || 0;
      let next = Math.max(0, Math.round((cur + delta) / 100) * 100);
      inp.value = next > 0 ? next : '';
      if (rng) rng.value = Math.min(25000, next);
      if (lbl) lbl.textContent = (typeof formatMoney === 'function') ? formatMoney(next) : next + ' ج.م';
      initRequestAllocations();
    }

    // تعديل تخصيص كل سطر بمقدار 100 جنيه
    function adjustAllocRowAmount(idx, delta) {
      if (!currentRequestAllocations[idx]) return;
      let cur = parseFloat(currentRequestAllocations[idx].amount) || 0;
      let next = Math.max(0, Math.round((cur + delta) / 100) * 100);
      currentRequestAllocations[idx].amount = next;
      renderRequestAllocations();
    }

    function initRequestAllocations() {
      const amtInp = document.getElementById('inpReqAmount');
      const rng = document.getElementById('rngReqAmount');
      const lbl = document.getElementById('lblReqSliderVal');
      const val = parseFloat(amtInp ? amtInp.value : 0) || 0;
      if (rng && document.activeElement !== rng) {
        rng.value = Math.min(25000, val);
      }
      if (lbl) {
        lbl.textContent = (typeof formatMoney === 'function') ? formatMoney(val) : val + ' ج.م';
      }
      const currentMember = document.getElementById('inpReqMember')?.value || 'أية';
      if (currentRequestAllocations.length === 0) {
        currentRequestAllocations = [{ amount: val, category: 'daily', member: currentMember }];
      } else if (currentRequestAllocations.length === 1) {
        currentRequestAllocations[0].amount = val;
        currentRequestAllocations[0].member = currentMember;
      }
      renderRequestAllocations();
    }

    function addRequestAllocationRow(amount = 0, category = 'daily', member = 'أية') {
      const totalRequested = parseFloat(document.getElementById('inpReqAmount')?.value || 0) || 0;
      let alreadyAllocated = 0;
      currentRequestAllocations.forEach(a => alreadyAllocated += (parseFloat(a.amount) || 0));
      const remaining = Math.max(0, totalRequested - alreadyAllocated);
      const initAmt = amount > 0 ? amount : remaining;

      currentRequestAllocations.push({
        amount: initAmt,
        category: category,
        member: member
      });
      renderRequestAllocations();
    }

    function removeRequestAllocationRow(idx) {
      if (currentRequestAllocations.length <= 1) {
        showToast('⚠️ يجب الإبقاء على سطر توزيع واحد على الأقل');
        return;
      }
      currentRequestAllocations.splice(idx, 1);
      renderRequestAllocations();
    }

    function updateRequestAllocationRow(idx, field, value) {
      if (!currentRequestAllocations[idx]) return;
      if (field === 'amount') {
        currentRequestAllocations[idx].amount = parseFloat(value) || 0;
      } else {
        currentRequestAllocations[idx][field] = value;
      }
      updateRequestAllocationBalances();
    }

    function updateRequestAllocationBalances() {
      const totalRequested = parseFloat(document.getElementById('inpReqAmount')?.value || 0) || 0;
      let allocatedSum = 0;
      (currentRequestAllocations || []).forEach(a => allocatedSum += (parseFloat(a.amount) || 0));
      const remaining = totalRequested - allocatedSum;

      const statusBadge = document.getElementById('allocMatchStatus');
      const summaryEl = document.getElementById('reqAllocSummaryTxt');
      const progressEl = document.getElementById('reqAllocProgressBar');

      const pct = totalRequested > 0 ? ((allocatedSum / totalRequested) * 100).toFixed(0) : 0;

      if (statusBadge) {
        if (totalRequested <= 0) {
          statusBadge.innerHTML = '<span style="color: #94a3b8;"><i class="fa-solid fa-pen"></i> حدد المبلغ أولاً</span>';
          statusBadge.style.background = 'rgba(255,255,255,0.06)';
          statusBadge.style.borderColor = 'rgba(255,255,255,0.15)';
        } else if (Math.abs(remaining) < 0.01) {
          statusBadge.innerHTML = `<span style="color: #10b981;"><i class="fa-solid fa-circle-check"></i> ✔ متطابق 100% (${formatMoney(totalRequested)})</span>`;
          statusBadge.style.background = 'rgba(16, 185, 129, 0.16)';
          statusBadge.style.borderColor = 'rgba(16, 185, 129, 0.45)';
        } else if (remaining > 0) {
          statusBadge.innerHTML = `<span style="color: #fbbf24;"><i class="fa-solid fa-triangle-exclamation"></i> ⚠️ متبقي غير موزع: ${formatMoney(remaining)} (${pct}% / 100%)</span>`;
          statusBadge.style.background = 'rgba(245, 158, 11, 0.16)';
          statusBadge.style.borderColor = 'rgba(245, 158, 11, 0.45)';
        } else {
          statusBadge.innerHTML = `<span style="color: #f43f5e;"><i class="fa-solid fa-circle-xmark"></i> ❌ تجاوز للمطلوب بـ: ${formatMoney(Math.abs(remaining))} (${pct}% / 100%)</span>`;
          statusBadge.style.background = 'rgba(244, 63, 94, 0.16)';
          statusBadge.style.borderColor = 'rgba(244, 63, 94, 0.45)';
        }
      }

      if (summaryEl) {
        summaryEl.innerHTML = `المبلغ المطلوب: <strong>${formatMoney(totalRequested)}</strong> | الموزع: <strong>${formatMoney(allocatedSum)}</strong> (${pct}%)`;
      }

      if (progressEl) {
        const barPct = totalRequested > 0 ? Math.min(100, Math.max(0, (allocatedSum / totalRequested) * 100)) : 0;
        progressEl.style.width = barPct + '%';
        progressEl.style.background = (remaining < -0.01) ? '#f43f5e' : (Math.abs(remaining) < 0.01 ? '#10b981' : '#fbbf24');
      }
    }

    // إدارة التقاط ورفع صور وفواتير طلب المصروف
    function handleRequestPhotoUpload(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = function(e) {
        if (file.type && file.type.startsWith('image/')) {
          const img = new Image();
          img.onload = function() {
            const canvas = document.createElement('canvas');
            const maxDim = 600;
            let w = img.width;
            let h = img.height;
            if (w > h && w > maxDim) {
              h = Math.round((h * maxDim) / w);
              w = maxDim;
            } else if (h > maxDim) {
              w = Math.round((w * maxDim) / h);
              h = maxDim;
            }
            canvas.width = w;
            canvas.height = h;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, w, h);
            const compressed = canvas.toDataURL('image/jpeg', 0.82);

            state.pendingRequestPhotoDataUri = compressed;

            const previewImg = document.getElementById('reqPhotoPreviewImg');
            const previewCont = document.getElementById('reqPhotoPreviewContainer');
            const badge = document.getElementById('reqPhotoStatusBadge');
            const fileNameEl = document.getElementById('reqPhotoFileName');

            if (previewImg) previewImg.src = compressed;
            if (previewCont) previewCont.style.display = 'flex';
            if (badge) badge.style.display = 'inline-flex';
            if (fileNameEl) fileNameEl.textContent = file.name || 'صورة ملتقطة بالكاميرا';
            showToast('📸 تم تجهيز صورة المستند للطلب بنجاح');
          };
          img.src = e.target.result;
        } else {
          // ملف مستند PDF أو غيره
          state.pendingRequestPhotoDataUri = e.target.result;
          const previewCont = document.getElementById('reqPhotoPreviewContainer');
          const badge = document.getElementById('reqPhotoStatusBadge');
          const fileNameEl = document.getElementById('reqPhotoFileName');
          if (previewCont) previewCont.style.display = 'flex';
          if (badge) badge.style.display = 'inline-flex';
          if (fileNameEl) fileNameEl.textContent = file.name || 'مستند مرفق';
          showToast('📄 تم إرفاق المستند بنجاح');
        }
      };
      reader.readAsDataURL(file);
    }

    function removeRequestPhoto() {
      state.pendingRequestPhotoDataUri = null;
      const previewCont = document.getElementById('reqPhotoPreviewContainer');
      const badge = document.getElementById('reqPhotoStatusBadge');
      const camInp = document.getElementById('inpReqCameraPhoto');
      const docInp = document.getElementById('inpReqDocFile');
      if (previewCont) previewCont.style.display = 'none';
      if (badge) badge.style.display = 'none';
      if (camInp) camInp.value = '';
      if (docInp) docInp.value = '';
    }

