    window.currentRequestStatusFilter = 'all';

    function setRequestStatusFilter(status) {
      window.currentRequestStatusFilter = status;
      const filterMap = {
        all: 'btnReqFilterAll',
        pending: 'btnReqFilterPending',
        approved: 'btnReqFilterApproved',
        rejected: 'btnReqFilterRejected'
      };
      Object.keys(filterMap).forEach(k => {
        const btn = document.getElementById(filterMap[k]);
        if (btn) {
          if (k === status) {
            btn.classList.add('active');
            btn.style.background = 'linear-gradient(135deg, #ec4899, #be185d)';
            btn.style.color = '#fff';
            btn.style.borderColor = 'rgba(244, 114, 182, 0.6)';
          } else {
            btn.classList.remove('active');
            btn.style.background = 'rgba(15, 23, 42, 0.8)';
            btn.style.color = '#94a3b8';
            btn.style.borderColor = 'rgba(255, 255, 255, 0.12)';
          }
        }
      });
      renderRequestsList();
    }

    function renderRequestsList() {
      const container = document.getElementById('requestsListContainer');
      if (!container) return;

      const allReqs = state.moneyRequests || [];
      let list = allReqs;

      // فلترة حسب العضو إن كان محدد
      if (state.currentMemberFilter && state.currentMemberFilter !== 'الكل') {
        list = list.filter(r => r.member === state.currentMemberFilter || (state.currentMemberFilter === 'البيت' && (r.member === 'البيت' || r.member === 'العائلة')));
      }

      // مزامنة العدادات بدقة تامة
      const totalCount = list.length;
      const pendingRequests = list.filter(r => r.status === 'pending');
      const pendingCount = pendingRequests.length;
      const pendingTotalAmt = pendingRequests.reduce((s, r) => s + (Number(r.amount) || 0), 0);

      const countBadge = document.getElementById('reqListCountBadge');
      if (countBadge) countBadge.textContent = `${totalCount} طلب`;

      const cAll = document.getElementById('cntReqAll');
      const cPend = document.getElementById('cntReqPending');
      const cAppr = document.getElementById('cntReqApproved');
      const cRej = document.getElementById('cntReqRejected');
      if (cAll) cAll.textContent = totalCount;
      if (cPend) cPend.textContent = pendingCount;
      if (cAppr) cAppr.textContent = list.filter(r => r.status === 'approved').length;
      if (cRej) cRej.textContent = list.filter(r => r.status === 'rejected').length;

      const pendingBadge = document.getElementById('reqPendingCountBadge');
      if (pendingBadge) pendingBadge.textContent = `${pendingCount} معلق`;

      const tabBadge = document.getElementById('reqPendingBadgeTab');
      if (tabBadge) tabBadge.textContent = `${pendingCount}`;

      const pendingSumEl = document.getElementById('reqPendingTotalAmount');
      if (pendingSumEl) pendingSumEl.textContent = formatMoney(pendingTotalAmt);

      // تصفية حسب حالة الطلب المحددة
      const statusFilter = window.currentRequestStatusFilter || 'all';
      if (statusFilter !== 'all') {
        list = list.filter(r => r.status === statusFilter);
      }

      if (list.length === 0) {
        container.innerHTML = `
          <div class="empty-state" style="padding: 24px 10px; text-align: center; background: rgba(15, 23, 42, 0.4); border-radius: 14px; border: 1px dashed rgba(255, 255, 255, 0.1);">
            <i class="fa-solid fa-hand-holding-dollar" style="color: #ec4899; font-size: 2rem; margin-bottom: 8px;"></i>
            <div class="empty-title" style="color: #cbd5e1; font-weight: 850; font-size: 0.88rem;">لا توجد طلبات في هذا القسم</div>
            <div class="empty-desc" style="color: #64748b; font-size: 0.72rem; margin-top: 4px;">يمكن لأية أو أي فرد في العائلة تقديم طلب مصروف جديد مع تحديد التوزيع التقديري</div>
          </div>
        `;
        return;
      }

      const attr = value => escapeHtml(value).replaceAll('"', '&quot;');
      const statuses = {
        pending: ['قيد الانتظار', 'fa-hourglass-half'],
        approved: ['تم الصرف', 'fa-circle-check'],
        rejected: ['مرفوض', 'fa-circle-xmark']
      };
      const actions = {approve: approveRequest, edit: promptEditMoneyRequest, reject: rejectRequest, delete: deleteRequest};
      container.innerHTML = '';
      list.forEach(req => {
        const card = document.createElement('article');
        card.className = 'req-card-lux request-card';
        const status = Object.hasOwn(statuses, req.status) ? req.status : 'rejected';
        const [statusLabel, statusIcon] = statuses[status];
        const allocations = Array.isArray(req.allocations) ? req.allocations : [];
        const allocationRows = allocations.map(allocation => {
          const category = getCategoryObj(allocation.category, 'expense');
          const member = allocation.member ? ` · ${escapeHtml(allocation.member)}` : '';
          return `<li><span><i class="fa-solid ${escapeHtml(category?.icon || 'fa-tag')}" aria-hidden="true"></i> ${escapeHtml(category?.name || 'مصروف')}${member}</span><bdi>${escapeHtml(formatMoney(allocation.amount))}</bdi></li>`;
        }).join('');
        card.innerHTML = `
          <header class="request-card-heading">
            <h3>${escapeHtml(req.reason || 'طلب مصروف')}</h3>
            <bdi class="request-card-total">${escapeHtml(formatMoney(req.amount))}</bdi>
          </header>
          <div class="request-card-meta">
            <span><i class="fa-solid fa-user" aria-hidden="true"></i> ${escapeHtml(req.member || 'العائلة')}</span>
            <span class="request-card-status" data-status="${status}"><i class="fa-solid ${statusIcon}" aria-hidden="true"></i> ${statusLabel}</span>
            <bdi class="request-card-serial">${escapeHtml(req.serialNo || req.auditSerial || '#REQ-2026')}</bdi>
            ${req.isModified ? `<span title="تم التعديل: ${attr(req.lastModifiedReason || '')}">معدّل</span>` : ''}
          </div>
          ${allocationRows ? `<ul class="request-card-allocations" aria-label="توزيع مبلغ الطلب">${allocationRows}</ul>` : ''}
          <div class="request-card-dates">
            <span><i class="fa-regular fa-calendar-check" aria-hidden="true"></i> تاريخ الحاجة <bdi>${escapeHtml(req.date || 'اليوم')}</bdi></span>
            ${req.timestamp ? `<span><i class="fa-regular fa-clock" aria-hidden="true"></i> تم الطلب <bdi>${escapeHtml(req.timestamp)}</bdi></span>` : ''}
          </div>
          ${req.photo ? `<a class="request-card-attachment" href="${attr(req.photo)}" target="_blank" rel="noopener" download="request-doc-${attr(req.id)}">
            <i class="fa-solid fa-paperclip" aria-hidden="true"></i> عرض المستند / الفاتورة المرفقة
          </a>` : ''}
          <div class="request-card-actions${status === 'pending' ? ' is-pending' : ''}">
            ${status === 'pending' ? `
            <button type="button" class="request-card-confirm" data-action="approve" title="موافقة وصرف فوراً"><i class="fa-solid fa-check" aria-hidden="true"></i><span>موافقة وصرف فوراً</span></button>
            <button type="button" data-action="edit" title="تعديل تفاصيل الطلب"><i class="fa-solid fa-pen-to-square" aria-hidden="true"></i><span>تعديل</span></button>
            <button type="button" class="request-card-danger" data-action="reject" title="رفض الطلب"><i class="fa-solid fa-xmark" aria-hidden="true"></i><span>رفض</span></button>
            ` : `<button type="button" class="request-card-danger" data-action="delete" title="حذف من السجل"><i class="fa-solid fa-trash-can" aria-hidden="true"></i><span>حذف</span></button>`}
          </div>`;
        card.querySelector('.request-card-actions').addEventListener('click', event => {
          const button = event.target.closest('button[data-action]');
          if (button) actions[button.dataset.action](req.id);
        });
        container.appendChild(card);
      });

    }

    function approveRequest(reqId) {
      const req = (state.moneyRequests || []).find(r => r.id === reqId);
      if (!req) return;

      const walletId = state.currentWalletId && state.currentWalletId !== 'all' ? state.currentWalletId : (state.wallets[0] ? state.wallets[0].id : 'wallet-ahly');
      const reqDate = req.date || new Date().toISOString().split('T')[0];

      // تسجيل الطلب وبياناته كالتزام فوري في صفحة الالتزامات المتوقعة (بناءً على طلب المستخدم)
      if (!state.expectedExpenses || !Array.isArray(state.expectedExpenses)) {
        state.expectedExpenses = [];
      }

      const commitmentFromReq = {
        id: 'exp-req-' + req.id,
        type: 'upcoming_bill',
        title: `طلب معتمد: ${req.reason || 'طلب مصروف عائلي'}`,
        amount: Number(req.amount) || 0,
        dueDate: reqDate,
        member: req.member || 'أية',
        status: 'upcoming',
        photo: req.receipt || null,
        allocations: req.allocations || [],
        notes: `تم اعتماد الطلب بواسطة (${state.currentUser || 'ماهر'}) - مسجل كالتزام متوقع`
      };

      state.expectedExpenses.unshift(commitmentFromReq);
      try {
        localStorage.setItem('family_monefy_expected', JSON.stringify(state.expectedExpenses));
      } catch(e) {}

      req.status = 'approved';
      req.approvedAt = new Date().toISOString();
      req.approvedBy = state.currentUser || 'ماهر';
      localStorage.setItem('family_monefy_requests', JSON.stringify(state.moneyRequests));

      logActivity({
        type: 'approve_request',
        action: 'اعتماد طلب مصروف',
        label: `اعتماد وصرف طلب: ${req.reason || 'طلب عائلي'}`,
        amount: Number(req.amount) || 0,
        member: req.member || 'أية',
        author: state.currentUser || 'ماهر',
        receipt: req.photo || null,
        notes: 'تم اعتماد الطلب وتثبيته كالتزام فوري'
      });

      renderRequestsList();
      renderUI();
      saveEmailVault();
      showToast(`✅ تمت الموافقة وصرف (${req.amount} ج.م) وتسجيل الحركات بالبند بنجاح`);
    }

    function rejectRequest(reqId) {
      const req = (state.moneyRequests || []).find(r => r.id === reqId);
      if (!req) return;
      req.status = 'rejected';
      localStorage.setItem('family_monefy_requests', JSON.stringify(state.moneyRequests));

      logActivity({
        type: 'reject_request',
        action: 'رفض طلب مصروف',
        label: `رفض طلب: ${req.reason || 'طلب عائلي'}`,
        amount: Number(req.amount) || 0,
        member: req.member || 'أية',
        author: state.currentUser || 'ماهر',
        notes: 'تم رفض هذا الطلب'
      });

      renderRequestsList();
      showToast('❌ تم رفض الطلب');
    }

    function deleteRequest(reqId) {
      const req = (state.moneyRequests || []).find(r => r.id === reqId);
      if (!req) return;

      const reason = prompt(`يرجى كتابة سبب حذف طلب المصروف [${req.serialNo || req.auditSerial || req.id}] (إلزامي للرقابة المالية):`);
      if (reason === null) return;
      const trimmed = reason.trim();
      if (!trimmed) {
        showToast('❌ تم إلغاء الحذف: كتابة سبب الحذف إلزامي للرقابة المالية والتدقيق', 'error', 4500);
        return;
      }

      // أرشفة الطلب المحذوف في الأرشيف الدائم
      state.deletedRequests = state.deletedRequests || [];
      req.deletedAt = new Date().toISOString();
      req.deletedBy = state.currentUser || 'ماهر';
      req.deletionReason = trimmed;
      state.deletedRequests.unshift(req);
      try {
        localStorage.setItem('family_deleted_requests_archive', JSON.stringify(state.deletedRequests));
      } catch(e) {}

      state.moneyRequests = (state.moneyRequests || []).filter(r => r.id !== reqId);
      try {
        localStorage.setItem('family_monefy_requests', JSON.stringify(state.moneyRequests));
      } catch(e) {}

      logActivity({
        type: 'request_deleted',
        action: 'حذف طلب مصروف',
        label: `قام [${state.currentUser || 'ماهر'}] بحذف طلب المصروف ${req.serialNo || req.id} (${formatMoney(req.amount)}) - السبب: ${trimmed}`,
        amount: req.amount,
        member: req.member,
        author: state.currentUser || 'ماهر',
        serial: req.serialNo || req.auditSerial
      });

      renderRequestsList();
      renderActivityLogUI();
      showToast(`🗑️ تم حذف وأرشفة طلب المصروف [${req.serialNo || req.id}] بنجاح (السبب: ${trimmed})`, 'info', 5000);
    }

