    function appearanceContrastRatio(foreground, background) {
      const parse = value => {
        const nums = String(value).match(/[\d.]+/g);
        if (!nums || nums.length < 3) return null;
        return nums.slice(0, 3).map(Number).map(channel => {
          const c = channel / 255;
          return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
        });
      };
      const fg = parse(foreground), bg = parse(background);
      if (!fg || !bg) return 0;
      const lum = rgb => 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
      const a = lum(fg), b = lum(bg);
      return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
    }

    function appearanceMixColor(foreground, background, foregroundWeight) {
      const parseHex = value => {
        const match = String(value || '').match(/^#([\da-f]{3}|[\da-f]{6})$/i);
        if (!match) return null;
        const hex = match[1].length === 3 ? match[1].split('').map(char => char + char).join('') : match[1];
        return [0, 2, 4].map(index => parseInt(hex.slice(index, index + 2), 16));
      };
      const fg = parseHex(foreground), bg = parseHex(background);
      if (!fg || !bg) return background;
      return 'rgb(' + fg.map((channel, index) => Math.round(channel * foregroundWeight + bg[index] * (1 - foregroundWeight))).join(', ') + ')';
    }

    function updateAppearanceAccent() {
      const root = document.documentElement;
      const palette = APPEARANCE_PALETTES[state.appTheme] || APPEARANCE_PALETTES.navy;
      const isLight = document.body.classList.contains('light-theme');
      root.style.setProperty('--appearance-accent-text', isLight ? palette.light : palette.dark);
      root.style.setProperty('--appearance-swatch', palette.swatch);
      root.setAttribute('data-color-mode', isLight ? 'light' : 'dark');
      document.body.setAttribute('data-color-mode', isLight ? 'light' : 'dark');
    }

    function updateAppearancePreview() {
      const preview = document.getElementById('settingsThemePreview');
      if (!preview) return;
      preview.setAttribute('data-card-style', document.body.getAttribute('data-card-style') || 'glass');
      const card = preview.querySelector('.settings-live-preview-card');
      const badge = document.getElementById('appearanceContrastBadge');
      if (!card || !badge) return;
      const background = getComputedStyle(card).backgroundColor;
      const textNodes = [
        preview.querySelector('.settings-live-preview-copy strong'),
        preview.querySelector('.settings-live-preview-copy small'),
        preview.querySelector('.settings-live-preview-value')
      ].filter(Boolean);
      const backgrounds = [background];
      if (preview.getAttribute('data-card-style') === 'gradient') {
        const palette = APPEARANCE_PALETTES[state.appTheme] || APPEARANCE_PALETTES.navy;
        const isLight = document.body.classList.contains('light-theme');
        const surface = isLight ? '#ffffff' : '#17243a';
        const accent = isLight ? palette.light : palette.dark;
        for (let tint = 0.01; tint <= 0.09; tint += 0.01) {
          backgrounds.push(appearanceMixColor(accent, surface, tint));
        }
      }
      const ratios = textNodes.map(node => Math.min(...backgrounds.map(color => appearanceContrastRatio(getComputedStyle(node).color, color))));
      const minimum = ratios.length ? Math.min(...ratios) : 0;
      badge.textContent = 'تباين ' + minimum.toFixed(1) + ':1 • WCAG AA';
      badge.classList.toggle('passes', minimum >= 4.5);
      badge.classList.toggle('fails', minimum < 4.5);
    }

    
